const html = "<!DOCTYPE html>\n<html lang=\"ko\" data-theme=\"light\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>KnHCommunity</title>\n \n<style>\n/* ==========================================\n   테마 변수\n========================================== */\n:root {\n    --accent: #4f7cff;\n    --accent-2: #8a5cff;\n    --accent-text: #ffffff;\n    --bg: #f1f4fb;\n    --bg-grad: radial-gradient(1200px 500px at 10% -10%, #dfe8ff 0%, transparent 60%),\n               radial-gradient(900px 500px at 100% 0%, #efe3ff 0%, transparent 55%);\n    --surface: #ffffff;\n    --surface-2: #f6f8fd;\n    --text: #1f2430;\n    --muted: #7a8296;\n    --border: #e2e7f2;\n    --shadow: 0 6px 24px rgba(40, 60, 120, .08);\n    --radius: 14px;\n    --font-size: 15px;\n}\n \n[data-theme=\"dark\"] {\n    --accent: #6c8cff;\n    --accent-2: #a37cff;\n    --bg: #0f1220;\n    --bg-grad: radial-gradient(1000px 500px at 10% -10%, #1b2250 0%, transparent 60%),\n               radial-gradient(800px 500px at 100% 0%, #2a1b4a 0%, transparent 55%);\n    --surface: #181c30;\n    --surface-2: #1f243b;\n    --text: #e8ebf7;\n    --muted: #8e97b5;\n    --border: #2a3050;\n    --shadow: 0 6px 24px rgba(0, 0, 0, .35);\n}\n \n[data-theme=\"ocean\"] {\n    --accent: #0aa5c9;\n    --accent-2: #2563eb;\n    --bg: #eaf7fb;\n    --bg-grad: radial-gradient(1000px 500px at 0% -10%, #c9eefa 0%, transparent 60%),\n               radial-gradient(800px 500px at 100% 0%, #d6e4ff 0%, transparent 55%);\n    --surface: #ffffff;\n    --surface-2: #f0fafd;\n    --text: #12303a;\n    --muted: #6b8c97;\n    --border: #d3ebf2;\n}\n \n[data-theme=\"forest\"] {\n    --accent: #2f9e6a;\n    --accent-2: #8bb832;\n    --bg: #eef6f0;\n    --bg-grad: radial-gradient(1000px 500px at 0% -10%, #d3efdc 0%, transparent 60%),\n               radial-gradient(800px 500px at 100% 0%, #ecf3cf 0%, transparent 55%);\n    --surface: #ffffff;\n    --surface-2: #f3faf5;\n    --text: #1b2b21;\n    --muted: #71897a;\n    --border: #d9eadf;\n}\n \n[data-theme=\"sunset\"] {\n    --accent: #ff6b4a;\n    --accent-2: #ff9f1c;\n    --bg: #fff3ec;\n    --bg-grad: radial-gradient(1000px 500px at 0% -10%, #ffe0d0 0%, transparent 60%),\n               radial-gradient(800px 500px at 100% 0%, #fff0c9 0%, transparent 55%);\n    --surface: #ffffff;\n    --surface-2: #fff8f4;\n    --text: #33211b;\n    --muted: #9a7f74;\n    --border: #f5dfd3;\n}\n \n[data-theme=\"sakura\"] {\n    --accent: #ec5f9a;\n    --accent-2: #b25bf0;\n    --bg: #fdf0f6;\n    --bg-grad: radial-gradient(1000px 500px at 0% -10%, #fbd3e5 0%, transparent 60%),\n               radial-gradient(800px 500px at 100% 0%, #ead7fb 0%, transparent 55%);\n    --surface: #ffffff;\n    --surface-2: #fef6fa;\n    --text: #35202b;\n    --muted: #9b7c8c;\n    --border: #f4dce7;\n}\n \n[data-theme=\"midnight\"] {\n    --accent: #00d4aa;\n    --accent-2: #00a3ff;\n    --accent-text: #04120f;\n    --bg: #05070d;\n    --bg-grad: radial-gradient(1000px 500px at 10% -10%, #06241f 0%, transparent 60%),\n               radial-gradient(800px 500px at 100% 0%, #081a2e 0%, transparent 55%);\n    --surface: #0d111c;\n    --surface-2: #131928;\n    --text: #e6f1ee;\n    --muted: #7d8f98;\n    --border: #1c2436;\n    --shadow: 0 6px 24px rgba(0, 0, 0, .55);\n}\n \n/* ==========================================\n   기본\n========================================== */\n* { box-sizing: border-box; }\n \nhtml { scroll-behavior: smooth; }\n \nbody {\n    margin: 0;\n    background: var(--bg);\n    background-image: var(--bg-grad);\n    background-attachment: fixed;\n    color: var(--text);\n    font-family: \"Pretendard\", \"Segoe UI\", \"Malgun Gothic\", Arial, sans-serif;\n    font-size: var(--font-size);\n    line-height: 1.7;\n    transition: background .3s, color .3s;\n}\n \nbutton, input, textarea, select { font-family: inherit; }\nbutton { cursor: pointer; }\n \n/* ==========================================\n   헤더\n========================================== */\nheader {\n    position: sticky;\n    top: 0;\n    z-index: 50;\n    height: 64px;\n    display: flex;\n    align-items: center;\n    gap: 22px;\n    padding: 0 28px;\n    background: linear-gradient(120deg, var(--accent), var(--accent-2));\n    color: var(--accent-text);\n    box-shadow: 0 4px 20px rgba(0, 0, 0, .18);\n}\n \n.logo {\n    font-size: 22px;\n    font-weight: 800;\n    letter-spacing: -.5px;\n    cursor: pointer;\n    white-space: nowrap;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n}\n \n.logo-mark {\n    width: 34px;\n    height: 34px;\n    border-radius: 10px;\n    background: rgba(255, 255, 255, .22);\n    display: grid;\n    place-items: center;\n    font-size: 15px;\n    font-weight: 900;\n    backdrop-filter: blur(6px);\n}\n \n.search { flex: 1; max-width: 520px; position: relative; }\n \n.search input {\n    width: 100%;\n    padding: 10px 16px 10px 40px;\n    border: none;\n    border-radius: 999px;\n    font-size: 14px;\n    background: rgba(255, 255, 255, .22);\n    color: inherit;\n    outline: none;\n    transition: background .2s, box-shadow .2s;\n}\n \n.search input::placeholder { color: rgba(255, 255, 255, .8); }\n \n.search input:focus {\n    background: rgba(255, 255, 255, .95);\n    color: #222;\n    box-shadow: 0 0 0 4px rgba(255, 255, 255, .25);\n}\n \n.search::before {\n    content: \"🔍\";\n    position: absolute;\n    left: 14px;\n    top: 50%;\n    transform: translateY(-50%);\n    font-size: 14px;\n    pointer-events: none;\n}\n \nnav { display: flex; align-items: center; gap: 6px; margin-left: auto; white-space: nowrap; }\n \nnav a, nav button {\n    color: inherit;\n    text-decoration: none;\n    cursor: pointer;\n    font-size: 14px;\n    padding: 8px 14px;\n    border-radius: 999px;\n    background: transparent;\n    border: none;\n    transition: background .2s;\n}\n \nnav a:hover, nav button:hover { background: rgba(255, 255, 255, .2); }\n \n/* ==========================================\n   레이아웃\n========================================== */\n.container {\n    max-width: 1280px;\n    margin: 26px auto;\n    display: grid;\n    grid-template-columns: 250px 1fr;\n    gap: 22px;\n    padding: 0 20px;\n    align-items: start;\n}\n \n.sidebar {\n    background: var(--surface);\n    border: 1px solid var(--border);\n    border-radius: var(--radius);\n    box-shadow: var(--shadow);\n    padding: 18px;\n    position: sticky;\n    top: 86px;\n}\n \n.sidebar h3 {\n    font-size: 12px;\n    letter-spacing: .08em;\n    text-transform: uppercase;\n    color: var(--muted);\n    margin: 4px 0 8px;\n}\n \n.sidebar h3:not(:first-child) { margin-top: 20px; }\n \n.sidebar a {\n    display: block;\n    padding: 9px 12px;\n    color: var(--text);\n    cursor: pointer;\n    text-decoration: none;\n    font-size: 14px;\n    border-radius: 10px;\n    transition: background .15s, transform .15s;\n}\n \n.sidebar a:hover {\n    background: var(--surface-2);\n    transform: translateX(3px);\n}\n \n.side-button {\n    width: 100%;\n    margin-top: 16px;\n    padding: 11px;\n    border: none;\n    border-radius: 12px;\n    background: linear-gradient(120deg, var(--accent), var(--accent-2));\n    color: var(--accent-text);\n    font-weight: 700;\n    box-shadow: 0 6px 16px rgba(0, 0, 0, .15);\n    transition: transform .15s, filter .15s;\n}\n \n.side-button:hover { transform: translateY(-2px); filter: brightness(1.07); }\n \nmain {\n    background: var(--surface);\n    border: 1px solid var(--border);\n    border-radius: var(--radius);\n    box-shadow: var(--shadow);\n    padding: 32px 36px;\n    min-height: 620px;\n    animation: fadeUp .35s ease;\n}\n \n@keyframes fadeUp {\n    from { opacity: 0; transform: translateY(8px); }\n    to { opacity: 1; transform: none; }\n}\n \n.title {\n    font-size: 30px;\n    margin: 0 0 18px;\n    padding-bottom: 14px;\n    border-bottom: 3px solid transparent;\n    border-image: linear-gradient(90deg, var(--accent), var(--accent-2), transparent) 1;\n    letter-spacing: -.5px;\n}\n \n.tabs {\n    display: flex;\n    gap: 6px;\n    flex-wrap: wrap;\n    margin-bottom: 22px;\n}\n \n.tabs button {\n    background: var(--surface-2);\n    color: var(--text);\n    border: 1px solid var(--border);\n    padding: 8px 16px;\n    border-radius: 999px;\n    font-size: 14px;\n    transition: all .15s;\n}\n \n.tabs button:hover { border-color: var(--accent); color: var(--accent); }\n \n.tabs button.active {\n    background: linear-gradient(120deg, var(--accent), var(--accent-2));\n    color: var(--accent-text);\n    border-color: transparent;\n}\n \n/* ==========================================\n   문서 본문\n========================================== */\n.info-box {\n    border: 1px solid var(--border);\n    border-left: 5px solid var(--accent);\n    background: var(--surface-2);\n    padding: 16px 20px;\n    margin: 18px 0;\n    border-radius: 10px;\n}\n \n.info-box h3 { margin: 0 0 6px; color: var(--accent); font-size: 16px; }\n \n.content h1 { font-size: 26px; margin: 20px 0 10px; }\n \n.content h2 {\n    font-size: 22px;\n    border-bottom: 1px solid var(--border);\n    padding-bottom: 8px;\n    margin-top: 32px;\n}\n \n.content h3 { font-size: 18px; margin-top: 22px; }\n \n.content p { margin: 10px 0; }\n \n.content a { color: var(--accent); cursor: pointer; text-decoration: none; font-weight: 600; }\n.content a:hover { text-decoration: underline; }\n \n.content ul { padding-left: 22px; }\n.content li { margin: 4px 0; }\n \n.content figure {\n    margin: 18px 0;\n    display: inline-block;\n    max-width: 100%;\n}\n \n.content img.wiki-img {\n    max-width: 100%;\n    max-height: 520px;\n    border-radius: 12px;\n    border: 1px solid var(--border);\n    box-shadow: var(--shadow);\n    cursor: zoom-in;\n    display: block;\n    transition: transform .2s;\n}\n \n.content img.wiki-img:hover { transform: scale(1.01); }\n \n.content figcaption {\n    font-size: 13px;\n    color: var(--muted);\n    text-align: center;\n    margin-top: 6px;\n}\n \n.broken-img {\n    display: inline-block;\n    padding: 10px 14px;\n    border: 1px dashed var(--border);\n    border-radius: 10px;\n    color: var(--muted);\n    font-size: 13px;\n}\n \n.toc {\n    border: 1px solid var(--border);\n    background: var(--surface-2);\n    padding: 14px 22px;\n    width: fit-content;\n    min-width: 220px;\n    margin: 22px 0;\n    border-radius: 12px;\n}\n \n.toc-title { font-weight: 800; text-align: center; margin-bottom: 8px; }\n \n.toc a {\n    display: block;\n    color: var(--accent);\n    text-decoration: none;\n    padding: 3px 4px;\n    font-size: 14px;\n}\n \n.toc a:hover { text-decoration: underline; }\n \nhr { border: none; border-top: 1px solid var(--border); margin: 28px 0 12px; }\n \n/* ==========================================\n   목록\n========================================== */\n.page-list { list-style: none; padding: 0; margin: 10px 0; display: grid; gap: 8px; }\n \n.page-list li {\n    padding: 13px 16px;\n    border: 1px solid var(--border);\n    background: var(--surface-2);\n    border-radius: 12px;\n    cursor: pointer;\n    transition: all .15s;\n}\n \n.page-list li:hover {\n    border-color: var(--accent);\n    transform: translateX(4px);\n    background: var(--surface);\n}\n \n.page-list a { color: var(--accent); text-decoration: none; font-weight: 600; }\n \n.page-list .sub { display: block; font-size: 12px; color: var(--muted); }\n \n.main-h2 { font-size: 19px; margin: 28px 0 8px; }\n \n/* ==========================================\n   편집기\n========================================== */\n.editor, .edit-title {\n    width: 100%;\n    border: 1px solid var(--border);\n    background: var(--surface-2);\n    color: var(--text);\n    border-radius: 12px;\n    outline: none;\n    transition: border-color .2s, box-shadow .2s;\n}\n \n.editor:focus, .edit-title:focus {\n    border-color: var(--accent);\n    box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent) 20%, transparent);\n}\n \n.editor {\n    min-height: 380px;\n    padding: 14px;\n    font-size: 15px;\n    font-family: \"JetBrains Mono\", Consolas, monospace;\n    resize: vertical;\n    line-height: 1.6;\n}\n \n.edit-title { padding: 12px 14px; margin-bottom: 14px; font-size: 17px; }\n \n.label { font-weight: 700; margin: 14px 0 6px; font-size: 14px; }\n \n.toolbar {\n    display: flex;\n    gap: 6px;\n    flex-wrap: wrap;\n    margin-bottom: 8px;\n}\n \n.toolbar button {\n    background: var(--surface-2);\n    border: 1px solid var(--border);\n    color: var(--text);\n    padding: 7px 12px;\n    border-radius: 9px;\n    font-size: 13px;\n    transition: all .15s;\n}\n \n.toolbar button:hover { border-color: var(--accent); color: var(--accent); }\n \n.toolbar .img-btn {\n    background: linear-gradient(120deg, var(--accent), var(--accent-2));\n    color: var(--accent-text);\n    border: none;\n}\n \n.toolbar .img-btn:hover { color: var(--accent-text); filter: brightness(1.08); }\n \n.dropzone-hint {\n    font-size: 12px;\n    color: var(--muted);\n    margin-top: 6px;\n}\n \n.editor.dragover {\n    border-color: var(--accent);\n    border-style: dashed;\n    background: color-mix(in srgb, var(--accent) 10%, var(--surface-2));\n}\n \n.attachments {\n    display: flex;\n    gap: 10px;\n    flex-wrap: wrap;\n    margin-top: 10px;\n}\n \n.thumb {\n    position: relative;\n    width: 96px;\n    height: 96px;\n    border-radius: 12px;\n    overflow: hidden;\n    border: 1px solid var(--border);\n    background: var(--surface-2);\n}\n \n.thumb img { width: 100%; height: 100%; object-fit: cover; display: block; cursor: pointer; }\n \n.thumb button {\n    position: absolute;\n    top: 4px;\n    right: 4px;\n    width: 22px;\n    height: 22px;\n    border-radius: 50%;\n    border: none;\n    background: rgba(0, 0, 0, .65);\n    color: #fff;\n    font-size: 12px;\n    line-height: 22px;\n    padding: 0;\n}\n \n.action, .secondary {\n    border: none;\n    padding: 11px 22px;\n    margin-top: 16px;\n    margin-right: 6px;\n    border-radius: 11px;\n    font-weight: 700;\n    transition: transform .15s, filter .15s;\n}\n \n.action {\n    background: linear-gradient(120deg, var(--accent), var(--accent-2));\n    color: var(--accent-text);\n    box-shadow: 0 6px 16px rgba(0, 0, 0, .12);\n}\n \n.secondary { background: var(--surface-2); color: var(--text); border: 1px solid var(--border); }\n \n.action:hover, .secondary:hover { transform: translateY(-2px); filter: brightness(1.05); }\n \n.status { color: var(--muted); font-size: 12px; margin-top: 14px; }\n \nfooter { text-align: center; color: var(--muted); padding: 30px; font-size: 13px; }\n \n/* ==========================================\n   설정 모달 / 라이트박스 / 토스트\n========================================== */\n.overlay {\n    position: fixed;\n    inset: 0;\n    z-index: 100;\n    background: rgba(10, 12, 25, .55);\n    backdrop-filter: blur(4px);\n    display: none;\n    align-items: center;\n    justify-content: center;\n    padding: 20px;\n}\n \n.overlay.show { display: flex; animation: fadeIn .2s ease; }\n \n@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }\n \n.modal {\n    width: 100%;\n    max-width: 560px;\n    max-height: 90vh;\n    overflow: auto;\n    background: var(--surface);\n    color: var(--text);\n    border: 1px solid var(--border);\n    border-radius: 18px;\n    padding: 26px;\n    box-shadow: 0 20px 60px rgba(0, 0, 0, .35);\n}\n \n.modal h2 { margin: 0 0 4px; }\n.modal .desc { color: var(--muted); font-size: 13px; margin: 0 0 18px; }\n \n.theme-grid {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 10px;\n}\n \n.theme-card {\n    border: 2px solid var(--border);\n    border-radius: 14px;\n    padding: 10px;\n    background: var(--surface-2);\n    color: var(--text);\n    text-align: center;\n    font-size: 13px;\n    transition: all .15s;\n}\n \n.theme-card:hover { transform: translateY(-2px); }\n.theme-card.active { border-color: var(--accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 25%, transparent); }\n \n.theme-swatch {\n    height: 44px;\n    border-radius: 9px;\n    margin-bottom: 8px;\n    border: 1px solid rgba(0, 0, 0, .08);\n}\n \n.setting-row {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 12px;\n    padding: 12px 0;\n    border-top: 1px solid var(--border);\n    margin-top: 14px;\n    font-size: 14px;\n}\n \n.setting-row input[type=color] {\n    width: 44px;\n    height: 32px;\n    border: none;\n    background: none;\n    padding: 0;\n    cursor: pointer;\n}\n \n.setting-row select, .setting-row input[type=range] { accent-color: var(--accent); }\n \n.setting-row select {\n    background: var(--surface-2);\n    color: var(--text);\n    border: 1px solid var(--border);\n    border-radius: 8px;\n    padding: 6px 10px;\n}\n \n.lightbox img {\n    max-width: 94vw;\n    max-height: 90vh;\n    border-radius: 12px;\n    box-shadow: 0 20px 60px rgba(0, 0, 0, .5);\n}\n \n.toast {\n    position: fixed;\n    bottom: 26px;\n    left: 50%;\n    transform: translateX(-50%) translateY(20px);\n    background: #222;\n    color: #fff;\n    padding: 12px 22px;\n    border-radius: 999px;\n    font-size: 14px;\n    opacity: 0;\n    pointer-events: none;\n    z-index: 200;\n    transition: all .3s;\n}\n \n.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }\n \n/* ==========================================\n   토론 (Discord 스타일)\n========================================== */\n.chat {\n    --c-bg: #313338;\n    --c-bg2: #2b2d31;\n    --c-bg3: #383a40;\n    --c-text: #dbdee1;\n    --c-muted: #949ba4;\n    --c-hover: #2e3035;\n    --c-line: #3f4147;\n    background: var(--c-bg);\n    color: var(--c-text);\n    border: 1px solid var(--c-line);\n    border-radius: calc(var(--radius) + 2px);\n    overflow: hidden;\n    display: flex;\n    flex-direction: column;\n    height: 660px;\n    max-height: 76vh;\n    box-shadow: var(--shadow);\n}\n \n.chat.dragover { outline: 2px dashed var(--accent); outline-offset: -6px; }\n \n.chat-head {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    padding: 12px 18px;\n    font-weight: 700;\n    border-bottom: 1px solid var(--c-line);\n    box-shadow: 0 1px 0 rgba(0, 0, 0, .2);\n}\n \n.chat-head .hash { color: var(--c-muted); font-size: 24px; font-weight: 400; line-height: 1; }\n \n.chat-sub {\n    flex: 1;\n    min-width: 0;\n    margin-left: 6px;\n    color: var(--c-muted);\n    font-size: 13px;\n    font-weight: 400;\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n}\n \n.chat-count { color: var(--c-muted); font-size: 12px; font-weight: 500; white-space: nowrap; }\n \n.chat-body { flex: 1; overflow-y: auto; padding: 8px 0 8px; }\n.chat-body::-webkit-scrollbar { width: 10px; }\n.chat-body::-webkit-scrollbar-thumb { background: #1a1b1e; border-radius: 8px; border: 2px solid var(--c-bg); }\n \n.chat-empty { text-align: center; color: var(--c-muted); padding: 90px 20px; }\n.chat-empty .big { font-size: 46px; margin-bottom: 8px; }\n.chat-empty b { color: var(--c-text); display: block; font-size: 18px; margin-bottom: 4px; }\n \n.day-div {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    margin: 18px 16px 6px;\n    color: var(--c-muted);\n    font-size: 12px;\n    font-weight: 600;\n}\n \n.day-div::before, .day-div::after { content: \"\"; flex: 1; height: 1px; background: var(--c-line); }\n \n.msg { position: relative; padding: 2px 18px; margin-top: 16px; }\n.msg.grouped { margin-top: 0; }\n.msg:hover { background: var(--c-hover); }\n.msg.mentioned { background: rgba(250, 166, 26, .1); box-shadow: inset 3px 0 0 #f0b232; }\n.msg.flash { animation: msgFlash 1.7s; }\n \n@keyframes msgFlash {\n    0%, 55% { background: rgba(88, 101, 242, .35); }\n    100% { background: transparent; }\n}\n \n.msg-row { display: flex; gap: 14px; }\n.msg-left { width: 40px; flex: none; text-align: center; }\n \n.avatar {\n    width: 40px;\n    height: 40px;\n    border-radius: 50%;\n    display: grid;\n    place-items: center;\n    color: #fff;\n    font-weight: 800;\n    font-size: 17px;\n    cursor: pointer;\n    text-shadow: 0 1px 2px rgba(0, 0, 0, .35);\n    transition: transform .15s;\n}\n \n.avatar:hover { transform: scale(1.08); }\n \n.hover-time { visibility: hidden; font-size: 10px; color: var(--c-muted); line-height: 22px; }\n.msg:hover .hover-time { visibility: visible; }\n \n.msg-main { min-width: 0; flex: 1; }\n.msg-meta { display: flex; align-items: baseline; gap: 8px; }\n.msg-name { font-weight: 700; cursor: pointer; }\n.msg-name:hover { text-decoration: underline; }\n.msg-time { font-size: 12px; color: var(--c-muted); }\n \n.msg-text { font-size: 15px; line-height: 1.55; overflow-wrap: anywhere; }\n.msg-text code { background: #1e1f22; padding: 1px 6px; border-radius: 4px; font-size: 13px; }\n.msg-text a { color: #00a8fc; text-decoration: none; font-weight: 500; }\n.msg-text a:hover { text-decoration: underline; }\n.edited { font-size: 11px; color: var(--c-muted); margin-left: 5px; }\n \n.mention {\n    background: rgba(88, 101, 242, .3);\n    color: #c9cdfb;\n    padding: 0 3px;\n    border-radius: 4px;\n    font-weight: 500;\n}\n \n.reply-ref {\n    display: flex;\n    align-items: center;\n    gap: 6px;\n    margin: 0 0 2px 54px;\n    font-size: 13px;\n    color: var(--c-muted);\n    cursor: pointer;\n    white-space: nowrap;\n    overflow: hidden;\n}\n \n.reply-ref span { overflow: hidden; text-overflow: ellipsis; }\n.reply-ref:hover span { color: var(--c-text); }\n.reply-ref.deleted { font-style: italic; cursor: default; }\n \n.chat-img {\n    display: block;\n    max-width: min(380px, 100%);\n    max-height: 300px;\n    border-radius: 8px;\n    margin-top: 6px;\n    cursor: zoom-in;\n}\n \n.reactions { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 4px; }\n \n.react {\n    display: inline-flex;\n    align-items: center;\n    gap: 5px;\n    padding: 2px 8px;\n    border-radius: 8px;\n    background: var(--c-bg3);\n    border: 1px solid transparent;\n    color: var(--c-text);\n    font-size: 14px;\n}\n \n.react span { font-size: 13px; font-weight: 600; }\n.react:hover { border-color: #6d6f78; }\n.react.mine { background: rgba(88, 101, 242, .25); border-color: #5865f2; }\n.react.add { color: var(--c-muted); }\n \n.msg-tools {\n    display: none;\n    position: absolute;\n    top: -14px;\n    right: 18px;\n    background: var(--c-bg2);\n    border: 1px solid var(--c-line);\n    border-radius: 8px;\n    overflow: hidden;\n    box-shadow: 0 4px 12px rgba(0, 0, 0, .35);\n    z-index: 2;\n}\n \n.msg:hover .msg-tools { display: flex; }\n.msg-tools button { background: none; border: none; color: var(--c-text); padding: 5px 9px; font-size: 15px; }\n.msg-tools button:hover { background: var(--c-bg3); }\n.msg-tools button.danger:hover { background: #f23f42; }\n \n.edit-box textarea {\n    width: 100%;\n    min-height: 46px;\n    background: var(--c-bg3);\n    color: var(--c-text);\n    border: none;\n    border-radius: 8px;\n    padding: 10px 12px;\n    font-size: 15px;\n    resize: vertical;\n    outline: none;\n}\n \n.edit-hint { font-size: 12px; color: var(--c-muted); margin-top: 4px; }\n \n.chat-compose { padding: 0 16px 10px; }\n \n.reply-bar {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    background: var(--c-bg2);\n    color: var(--c-muted);\n    font-size: 13px;\n    padding: 7px 12px;\n    border-radius: 8px 8px 0 0;\n}\n \n.reply-bar[hidden] { display: none; }\n.reply-bar b { color: var(--c-text); }\n.reply-bar button { background: none; border: none; color: var(--c-muted); font-size: 16px; }\n \n.pending { display: flex; flex-wrap: wrap; gap: 8px; background: var(--c-bg3); padding: 10px 12px; border-bottom: 1px solid var(--c-line); border-radius: 10px 10px 0 0; }\n.pending:empty { display: none; }\n \n.pending-item { position: relative; width: 84px; height: 84px; border-radius: 8px; overflow: hidden; background: #1e1f22; }\n.pending-item img { width: 100%; height: 100%; object-fit: cover; display: block; }\n \n.pending-item button {\n    position: absolute;\n    top: 3px;\n    right: 3px;\n    width: 20px;\n    height: 20px;\n    padding: 0;\n    border: none;\n    border-radius: 50%;\n    background: rgba(0, 0, 0, .7);\n    color: #fff;\n    font-size: 11px;\n}\n \n.compose-box { display: flex; align-items: flex-end; gap: 2px; background: var(--c-bg3); border-radius: 10px; padding: 4px 6px; }\n \n.compose-box textarea {\n    flex: 1;\n    min-width: 0;\n    background: none;\n    border: none;\n    outline: none;\n    color: var(--c-text);\n    font-size: 15px;\n    line-height: 1.4;\n    resize: none;\n    padding: 10px 6px;\n    max-height: 160px;\n}\n \n.compose-box textarea::placeholder { color: var(--c-muted); }\n \n.c-btn { background: none; border: none; color: var(--c-muted); font-size: 20px; padding: 8px 9px; border-radius: 6px; }\n.c-btn:hover { color: var(--c-text); background: rgba(255, 255, 255, .06); }\n \n.c-send {\n    background: linear-gradient(120deg, var(--accent), var(--accent-2));\n    color: var(--accent-text);\n    border: none;\n    font-weight: 700;\n    border-radius: 8px;\n    padding: 8px 16px;\n    margin: 4px 2px;\n}\n \n.c-send:hover { filter: brightness(1.1); }\n \n.who { font-size: 12px; color: var(--c-muted); padding: 7px 4px 0; }\n.who b { color: var(--c-text); }\n.who a { color: #00a8fc; cursor: pointer; }\n \n.emoji-pop {\n    position: fixed;\n    z-index: 150;\n    display: none;\n    grid-template-columns: repeat(6, 1fr);\n    gap: 2px;\n    width: 264px;\n    padding: 8px;\n    background: #2b2d31;\n    border: 1px solid #3f4147;\n    border-radius: 12px;\n    box-shadow: 0 10px 30px rgba(0, 0, 0, .45);\n}\n \n.emoji-pop.show { display: grid; }\n.emoji-pop button { background: none; border: none; font-size: 22px; padding: 6px; border-radius: 8px; }\n.emoji-pop button:hover { background: #3f4147; }\n \n@media (hover: none) {\n    .msg-tools { position: static; display: flex; width: fit-content; margin: 4px 0 2px 54px; }\n}\n \n/* ==========================================\n   반응형\n========================================== */\n@media (max-width: 860px) {\n    header { padding: 10px 14px; gap: 10px; height: auto; flex-wrap: wrap; position: static; }\n    .search { order: 3; flex-basis: 100%; max-width: none; }\n    .container { display: block; padding: 0 12px; }\n    .sidebar { position: static; margin-bottom: 16px; }\n    main { padding: 20px 18px; }\n    .theme-grid { grid-template-columns: repeat(2, 1fr); }\n}\n\n\n/* ==========================================\n   KnHCommunity 자유게시판 (Cloudflare API)\n========================================== */\n.board-wrap { width:100%; }\n.board-top { display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap; margin:18px 0; }\n.board-tools { display:flex; gap:8px; flex-wrap:wrap; align-items:center; }\n.board-tools input,.board-form input,.board-form textarea,.board-auth input,.board-comment-form textarea { box-sizing:border-box; border:1px solid var(--border); border-radius:10px; padding:11px 13px; background:var(--surface-2); color:var(--text); font:inherit; }\n.board-tools input { min-width:210px; }\n.board-btn { border:0; border-radius:10px; padding:10px 15px; background:var(--accent); color:var(--accent-text,#fff); cursor:pointer; font:inherit; font-weight:700; }\n.board-btn.secondary { background:var(--surface-2); color:var(--text); border:1px solid var(--border); }\n.board-btn.danger { background:#d94848; color:white; }\n.board-userbar { display:flex; gap:10px; align-items:center; flex-wrap:wrap; color:var(--muted); font-size:14px; }\n.board-table { width:100%; border-collapse:collapse; background:var(--surface); border:1px solid var(--border); border-radius:12px; overflow:hidden; }\n.board-table th,.board-table td { padding:13px 12px; border-bottom:1px solid var(--border); text-align:left; font-size:14px; }\n.board-table th { background:var(--surface-2); color:var(--muted); font-weight:700; }\n.board-table tr:last-child td { border-bottom:0; }\n.board-title-link { color:var(--text); cursor:pointer; font-weight:700; }\n.board-title-link:hover { color:var(--accent); }\n.board-muted { color:var(--muted); font-size:13px; }\n.board-empty { padding:42px 16px; text-align:center; color:var(--muted); border:1px dashed var(--border); border-radius:12px; }\n.board-pagination { display:flex; justify-content:center; align-items:center; gap:8px; margin:18px 0; }\n.board-form,.board-auth,.board-post,.board-comment { background:var(--surface); border:1px solid var(--border); border-radius:13px; padding:18px; margin:14px 0; }\n.board-form label,.board-auth label { display:block; font-weight:700; margin:12px 0 6px; }\n.board-form input,.board-form textarea,.board-auth input { width:100%; }\n.board-form textarea { min-height:260px; resize:vertical; line-height:1.65; }\n.board-auth { max-width:460px; margin:24px auto; }\n.board-auth h2 { margin-top:0; }\n.board-auth-actions { display:flex; gap:8px; margin-top:16px; }\n.board-post-head { border-bottom:1px solid var(--border); padding-bottom:14px; margin-bottom:16px; }\n.board-post-content { white-space:pre-wrap; overflow-wrap:anywhere; line-height:1.8; min-height:120px; }\n.board-comment { padding:13px 15px; }\n.board-comment p { white-space:pre-wrap; overflow-wrap:anywhere; margin:8px 0; }\n.board-comment-form textarea { width:100%; min-height:90px; resize:vertical; }\n.board-error { color:#d94848; margin-top:10px; font-size:14px; }\n@media(max-width:700px) { .board-table th:nth-child(3),.board-table td:nth-child(3),.board-table th:nth-child(4),.board-table td:nth-child(4) { display:none; } .board-table th,.board-table td { padding:11px 8px; } .board-tools input { min-width:0; width:100%; } }\n\n</style>\n</head>\n \n<body>\n \n<header>\n    <div class=\"logo\" onclick=\"home()\">\n        <span class=\"logo-mark\">K</span>KnHCommunity\n    </div>\n \n    <div class=\"search\">\n        <input\n            id=\"search\"\n            placeholder=\"문서 검색...\"\n            onkeydown=\"if(event.key==='Enter') searchPage()\"\n        >\n    </div>\n \n    <nav>\n        <a onclick=\"home()\">대문</a>\n        <a onclick=\"recentChanges()\">최근 변경</a>\n        <a onclick=\"openPage('사용자:주호')\">사용자</a>\n        <button onclick=\"openSettings()\" title=\"테마 설정\">🎨 테마</button>\n    </nav>\n</header>\n \n<div class=\"container\">\n \n    <aside class=\"sidebar\">\n \n        <h3>KnHCommunity 메뉴</h3>\n \n        <a onclick=\"home()\">🏠 대문</a>\n        <a onclick=\"allPages()\">📚 전체 문서</a>\n        <a onclick=\"recentChanges()\">🕒 최근 변경</a>\n        <a onclick=\"openPage('자유게시판')\">💬 자유게시판</a>\n        <a onclick=\"openSettings()\">🎨 테마 설정</a>\n \n        <h3>즐겨찾기</h3>\n        <div id=\"favorites\"></div>\n \n        <button class=\"side-button\" onclick=\"createPage()\">\n            + 새 문서 만들기\n        </button>\n \n        <p class=\"status\">KnHCommunity 0.3.0</p>\n \n    </aside>\n \n    <main id=\"main\"></main>\n \n</div>\n \n<footer>\n    Copyright © 2026 KnHCommunity.\n    Powered by HTML / CSS / JavaScript.\n</footer>\n \n<!-- 설정 모달 -->\n<div class=\"overlay\" id=\"settingsOverlay\" onclick=\"if(event.target===this) closeSettings()\">\n    <div class=\"modal\">\n        <h2>🎨 테마 설정</h2>\n        <p class=\"desc\">선택한 설정은 이 브라우저에 자동 저장됩니다.</p>\n \n        <div class=\"theme-grid\" id=\"themeGrid\"></div>\n \n        <div class=\"setting-row\">\n            <span>포인트 색상 (직접 지정)</span>\n            <span>\n                <input type=\"color\" id=\"accentPicker\" oninput=\"setCustomAccent(this.value)\">\n                <button class=\"secondary\" style=\"margin:0;padding:6px 12px\" onclick=\"resetAccent()\">초기화</button>\n            </span>\n        </div>\n \n        <div class=\"setting-row\">\n            <span>글자 크기</span>\n            <span>\n                <input type=\"range\" id=\"fontRange\" min=\"13\" max=\"20\" step=\"1\"\n                       oninput=\"setFontSize(this.value)\">\n                <b id=\"fontLabel\"></b>\n            </span>\n        </div>\n \n        <div class=\"setting-row\">\n            <span>모서리 둥글기</span>\n            <select id=\"radiusSelect\" onchange=\"setRadius(this.value)\">\n                <option value=\"4\">각진</option>\n                <option value=\"10\">보통</option>\n                <option value=\"14\">둥근</option>\n                <option value=\"22\">아주 둥근</option>\n            </select>\n        </div>\n \n        <button class=\"action\" onclick=\"closeSettings()\">닫기</button>\n    </div>\n</div>\n \n<!-- 이미지 확대 -->\n<div class=\"overlay lightbox\" id=\"lightbox\" onclick=\"this.classList.remove('show')\">\n    <img id=\"lightboxImg\" alt=\"\">\n</div>\n \n<div class=\"toast\" id=\"toast\"></div>\n \n<div class=\"emoji-pop\" id=\"emojiPop\"></div>\n \n<input type=\"file\" id=\"fileInput\" accept=\"image/*\" multiple hidden>\n \n<script>\n \n// ==========================================\n// 1. 데이터 관리\n// ==========================================\n \nconst STORAGE_KEY = \"knhcommunity_pages\";\nconst IMAGE_KEY = \"knhcommunity_images\";\nconst SETTINGS_KEY = \"knhcommunity_settings\";\nconst COMMENT_KEY = \"knhcommunity_comments\";\nconst USER_KEY = \"knhcommunity_user\";\n \nfunction load(key, fallback) {\n    try {\n        const v = JSON.parse(localStorage.getItem(key) || \"null\");\n        return v === null ? fallback : v;\n    } catch (e) {\n        return fallback;\n    }\n}\n \nlet pages = load(STORAGE_KEY, null);\nlet images = load(IMAGE_KEY, {});\nlet comments = load(COMMENT_KEY, {});\n \nif (!pages) {\n \n    pages = {\n        \"KnHCommunity\": {\n            title: \"KnHCommunity\",\n            content:\n`# KnHCommunity\n \nKnHCommunity에 오신 것을 환영합니다!\n \n친구들과 함께 문서를 만들고 소통하는 위키 커뮤니티입니다.\n \n## 1. 주요 기능\n \n- 위키 스타일 문서\n- 친구들의 프로필\n- 자유게시판\n- 문서 편집\n- **이미지 첨부** (편집 화면에서 버튼, 드래그, 붙여넣기)\n- **테마 설정** (우측 상단 🎨 버튼)\n \n## 2. 시작하기\n \n[[사용자:주호]] 문서를 확인해 보세요.\n \n[목차]`,\n            updated: Date.now()\n        },\n \n        \"사용자:주호\": {\n            title: \"사용자:주호\",\n            content:\n`# 김주호\n \nKnHCommunity의 사용자 문서입니다.\n \n## 1. 개요\n \n안녕하세요!\n \n## 2. 관심 분야\n \n- 게임 개발\n- Python\n- C++\n- 알고리즘\n \n## 3. 기타\n \n이 문서는 자유롭게 수정할 수 있습니다.`,\n            updated: Date.now()\n        },\n \n        \"자유게시판\": {\n            title: \"자유게시판\",\n            content:\n`# 자유게시판\n \nKnHCommunity의 자유게시판입니다.\n \n아직 게시판 기능은 개발 중입니다.`,\n            updated: Date.now()\n        }\n    };\n \n    saveData();\n}\n \nfunction saveData() {\n    try {\n        localStorage.setItem(STORAGE_KEY, JSON.stringify(pages));\n        localStorage.setItem(IMAGE_KEY, JSON.stringify(images));\n        localStorage.setItem(COMMENT_KEY, JSON.stringify(comments));\n        return true;\n    } catch (e) {\n        toast(\"저장 공간이 부족합니다. 이미지를 줄이거나 삭제해 주세요.\");\n        return false;\n    }\n}\n \n// ==========================================\n// 2. 유틸\n// ==========================================\n \nfunction escapeHTML(str) {\n    return String(str).replace(/[&<>\"']/g, char => ({\n        \"&\": \"&amp;\",\n        \"<\": \"&lt;\",\n        \">\": \"&gt;\",\n        '\"': \"&quot;\",\n        \"'\": \"&#39;\"\n    })[char]);\n}\n \nlet toastTimer;\nfunction toast(msg) {\n    const t = document.getElementById(\"toast\");\n    t.textContent = msg;\n    t.classList.add(\"show\");\n    clearTimeout(toastTimer);\n    toastTimer = setTimeout(() => t.classList.remove(\"show\"), 2400);\n}\n \nfunction uniqueTitle(base) {\n    if (!pages[base]) return base;\n    let i = 2;\n    while (pages[base + \" \" + i]) i++;\n    return base + \" \" + i;\n}\n \nfunction openLightbox(src) {\n    document.getElementById(\"lightboxImg\").src = src;\n    document.getElementById(\"lightbox\").classList.add(\"show\");\n}\n \n// ==========================================\n// 3. 테마 설정\n// ==========================================\n \nconst THEMES = [\n    { id: \"light\",    name: \"라이트\",   preview: \"linear-gradient(120deg,#4f7cff,#8a5cff)\" },\n    { id: \"dark\",     name: \"다크\",     preview: \"linear-gradient(120deg,#181c30,#6c8cff)\" },\n    { id: \"ocean\",    name: \"오션\",     preview: \"linear-gradient(120deg,#0aa5c9,#2563eb)\" },\n    { id: \"forest\",   name: \"포레스트\", preview: \"linear-gradient(120deg,#2f9e6a,#8bb832)\" },\n    { id: \"sunset\",   name: \"선셋\",     preview: \"linear-gradient(120deg,#ff6b4a,#ff9f1c)\" },\n    { id: \"sakura\",   name: \"사쿠라\",   preview: \"linear-gradient(120deg,#ec5f9a,#b25bf0)\" },\n    { id: \"midnight\", name: \"미드나잇\", preview: \"linear-gradient(120deg,#05070d,#00d4aa)\" }\n];\n \nlet settings = Object.assign(\n    { theme: \"light\", accent: \"\", fontSize: 15, radius: 14 },\n    load(SETTINGS_KEY, {})\n);\n \nfunction saveSettings() {\n    try { localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings)); } catch (e) {}\n}\n \nfunction hexToRgb(hex) {\n    const n = parseInt(hex.slice(1), 16);\n    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];\n}\n \nfunction shade(hex, amt) {\n    const [r, g, b] = hexToRgb(hex).map(v =>\n        Math.max(0, Math.min(255, Math.round(v + amt)))\n    );\n    return \"#\" + [r, g, b].map(v => v.toString(16).padStart(2, \"0\")).join(\"\");\n}\n \nfunction applySettings() {\n \n    const root = document.documentElement;\n \n    root.setAttribute(\"data-theme\", settings.theme);\n    root.style.setProperty(\"--font-size\", settings.fontSize + \"px\");\n    root.style.setProperty(\"--radius\", settings.radius + \"px\");\n \n    if (settings.accent) {\n        root.style.setProperty(\"--accent\", settings.accent);\n        root.style.setProperty(\"--accent-2\", shade(settings.accent, -45));\n \n        const [r, g, b] = hexToRgb(settings.accent);\n        const bright = (r * 299 + g * 587 + b * 114) / 1000;\n        root.style.setProperty(\"--accent-text\", bright > 170 ? \"#111\" : \"#fff\");\n    } else {\n        root.style.removeProperty(\"--accent\");\n        root.style.removeProperty(\"--accent-2\");\n        root.style.removeProperty(\"--accent-text\");\n    }\n}\n \nfunction renderThemeGrid() {\n \n    const grid = document.getElementById(\"themeGrid\");\n    grid.innerHTML = \"\";\n \n    THEMES.forEach(t => {\n \n        const btn = document.createElement(\"button\");\n        btn.className = \"theme-card\" + (settings.theme === t.id ? \" active\" : \"\");\n        btn.innerHTML = `<div class=\"theme-swatch\" style=\"background:${t.preview}\"></div>${t.name}`;\n \n        btn.onclick = () => {\n            settings.theme = t.id;\n            settings.accent = \"\";\n            saveSettings();\n            applySettings();\n            renderThemeGrid();\n            syncSettingInputs();\n        };\n \n        grid.appendChild(btn);\n    });\n}\n \nfunction syncSettingInputs() {\n    const cs = getComputedStyle(document.documentElement);\n    document.getElementById(\"accentPicker\").value =\n        settings.accent || normalizeHex(cs.getPropertyValue(\"--accent\").trim());\n    document.getElementById(\"fontRange\").value = settings.fontSize;\n    document.getElementById(\"fontLabel\").textContent = settings.fontSize + \"px\";\n    document.getElementById(\"radiusSelect\").value = String(settings.radius);\n}\n \nfunction normalizeHex(v) {\n    return /^#[0-9a-f]{6}$/i.test(v) ? v : \"#4f7cff\";\n}\n \nfunction setCustomAccent(v) {\n    settings.accent = v;\n    saveSettings();\n    applySettings();\n}\n \nfunction resetAccent() {\n    settings.accent = \"\";\n    saveSettings();\n    applySettings();\n    syncSettingInputs();\n}\n \nfunction setFontSize(v) {\n    settings.fontSize = Number(v);\n    document.getElementById(\"fontLabel\").textContent = v + \"px\";\n    saveSettings();\n    applySettings();\n}\n \nfunction setRadius(v) {\n    settings.radius = Number(v);\n    saveSettings();\n    applySettings();\n}\n \nfunction openSettings() {\n    renderThemeGrid();\n    syncSettingInputs();\n    document.getElementById(\"settingsOverlay\").classList.add(\"show\");\n}\n \nfunction closeSettings() {\n    document.getElementById(\"settingsOverlay\").classList.remove(\"show\");\n}\n \n// ==========================================\n// 4. 이미지 처리\n// ==========================================\n \nconst MAX_IMG_SIZE = 1280;\n \nfunction newImageId() {\n    return \"i\" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);\n}\n \n// 이미지 크기를 줄여서 저장 공간 절약\nfunction compressImage(file, maxSize = MAX_IMG_SIZE) {\n    return new Promise((resolve, reject) => {\n \n        const reader = new FileReader();\n \n        reader.onerror = reject;\n        reader.onload = () => {\n \n            const img = new Image();\n \n            img.onerror = reject;\n            img.onload = () => {\n \n                let { width, height } = img;\n                const ratio = Math.min(1, maxSize / Math.max(width, height));\n \n                width = Math.round(width * ratio);\n                height = Math.round(height * ratio);\n \n                const canvas = document.createElement(\"canvas\");\n                canvas.width = width;\n                canvas.height = height;\n \n                const ctx = canvas.getContext(\"2d\");\n                ctx.fillStyle = \"#fff\";\n                ctx.fillRect(0, 0, width, height);\n                ctx.drawImage(img, 0, 0, width, height);\n \n                resolve(canvas.toDataURL(\"image/jpeg\", 0.85));\n            };\n \n            img.src = reader.result;\n        };\n \n        reader.readAsDataURL(file);\n    });\n}\n \nasync function addImageFiles(files) {\n \n    const area = document.getElementById(\"editContent\");\n    if (!area) return;\n \n    for (const file of files) {\n \n        if (!file.type.startsWith(\"image/\")) {\n            toast(\"이미지 파일만 첨부할 수 있습니다.\");\n            continue;\n        }\n \n        try {\n            const data = await compressImage(file);\n            const id = newImageId();\n            images[id] = data;\n \n            const name = (file.name || \"이미지\").replace(/\\.[^.]+$/, \"\").replace(/[\\[\\]()]/g, \"\");\n            insertAtCursor(area, `\\n![${name}](img:${id})\\n`);\n \n        } catch (e) {\n            toast(\"이미지를 불러오지 못했습니다.\");\n        }\n    }\n \n    refreshAttachments();\n}\n \nfunction insertAtCursor(area, text) {\n    const start = area.selectionStart;\n    const end = area.selectionEnd;\n    area.value = area.value.slice(0, start) + text + area.value.slice(end);\n    area.selectionStart = area.selectionEnd = start + text.length;\n    area.focus();\n}\n \nfunction pickImages() {\n    const input = document.getElementById(\"fileInput\");\n    input.value = \"\";\n    input.onchange = () => addImageFiles(Array.from(input.files));\n    input.click();\n}\n \nconst IMG_REGEX = /!\\[([^\\]]*)\\]\\(img:(\\w+)\\)/g;\n \nfunction usedImageIds(text) {\n    return Array.from(text.matchAll(IMG_REGEX)).map(m => m[2]);\n}\n \nfunction refreshAttachments() {\n \n    const area = document.getElementById(\"editContent\");\n    const box = document.getElementById(\"attachments\");\n    if (!area || !box) return;\n \n    const ids = [...new Set(usedImageIds(area.value))];\n \n    box.innerHTML = \"\";\n \n    ids.forEach(id => {\n \n        if (!images[id]) return;\n \n        const div = document.createElement(\"div\");\n        div.className = \"thumb\";\n \n        const img = document.createElement(\"img\");\n        img.src = images[id];\n        img.onclick = () => openLightbox(images[id]);\n \n        const del = document.createElement(\"button\");\n        del.textContent = \"✕\";\n        del.title = \"문서에서 제거\";\n        del.onclick = () => {\n            area.value = area.value.replace(\n                new RegExp(\"\\\\n?!\\\\[[^\\\\]]*\\\\]\\\\(img:\" + id + \"\\\\)\\\\n?\", \"g\"),\n                \"\\n\"\n            );\n            refreshAttachments();\n        };\n \n        div.appendChild(img);\n        div.appendChild(del);\n        box.appendChild(div);\n    });\n}\n \n// 어떤 문서에서도 쓰이지 않는 이미지 정리\nfunction cleanupImages() {\n \n    const used = new Set();\n \n    Object.values(pages).forEach(p =>\n        usedImageIds(p.content).forEach(id => used.add(id))\n    );\n \n    // 토론(댓글)에 쓰인 이미지와 전송 대기 중인 이미지도 유지\n    Object.values(comments).forEach(list =>\n        list.forEach(m => (m.imgs || []).forEach(id => used.add(id)))\n    );\n    pendingImgs.forEach(id => used.add(id));\n \n    Object.keys(images).forEach(id => {\n        if (!used.has(id)) delete images[id];\n    });\n}\n \n// ==========================================\n// 5. 위키 문법 파서\n// ==========================================\n \nfunction renderWiki(text) {\n \n    const lines = text.split(\"\\n\");\n    let result = \"\";\n    let headings = [];\n    let listOpen = false;\n \n    for (let line of lines) {\n \n        if (line.trim() === \"[목차]\") {\n            if (listOpen) { result += \"</ul>\"; listOpen = false; }\n            result += \"{{TOC}}\";\n            continue;\n        }\n \n        if (listOpen && !line.startsWith(\"- \")) {\n            result += \"</ul>\";\n            listOpen = false;\n        }\n \n        if (line.startsWith(\"### \")) {\n            let title = line.substring(4);\n            headings.push({ level: 3, title });\n            result += `<h3>${escapeHTML(title)}</h3>`;\n        }\n \n        else if (line.startsWith(\"## \")) {\n            let title = line.substring(3);\n            headings.push({ level: 2, title });\n            result += `<h2>${escapeHTML(title)}</h2>`;\n        }\n \n        else if (line.startsWith(\"# \")) {\n            let title = line.substring(2);\n            headings.push({ level: 1, title });\n            result += `<h1>${escapeHTML(title)}</h1>`;\n        }\n \n        else if (line.startsWith(\"- \")) {\n \n            if (!listOpen) {\n                result += \"<ul>\";\n                listOpen = true;\n            }\n \n            result += `<li>${formatInline(line.substring(2))}</li>`;\n        }\n \n        else if (line.trim() === \"\") {\n            result += \"\";\n        }\n \n        else {\n            result += `<p>${formatInline(line)}</p>`;\n        }\n    }\n \n    if (listOpen) result += \"</ul>\";\n \n    const toc = `\n    <div class=\"toc\">\n        <div class=\"toc-title\">목차</div>\n        ${headings.map((h, i) =>\n            `<a href=\"#heading-${i}\">${i + 1}. ${escapeHTML(h.title)}</a>`\n        ).join(\"\")}\n    </div>`;\n \n    let index = 0;\n \n    result = result.replace(/<(h[123])>(.*?)<\\/h[123]>/g,\n        (match, tag, content) =>\n            `<${tag} id=\"heading-${index++}\">${content}</${tag}>`\n    );\n \n    result = result.replace(\"{{TOC}}\", toc);\n \n    return result;\n}\n \nfunction formatInline(text) {\n \n    let safe = escapeHTML(text);\n \n    // 이미지: ![설명](img:ID)\n    safe = safe.replace(/!\\[([^\\]]*)\\]\\(img:(\\w+)\\)/g,\n        (match, alt, id) => {\n \n            if (!images[id]) {\n                return `<span class=\"broken-img\">🖼 이미지를 찾을 수 없습니다</span>`;\n            }\n \n            return `<figure>\n                <img class=\"wiki-img\" data-img=\"${id}\" alt=\"${alt}\">\n                ${alt ? `<figcaption>${alt}</figcaption>` : \"\"}\n            </figure>`;\n        }\n    );\n \n    // [[문서명]]\n    safe = safe.replace(/\\[\\[(.*?)\\]\\]/g,\n        (match, title) => {\n \n            const encoded = encodeURIComponent(\n                title.replace(/&amp;/g, \"&\").replace(/&lt;/g, \"<\")\n                     .replace(/&gt;/g, \">\").replace(/&quot;/g, '\"')\n                     .replace(/&#39;/g, \"'\")\n            );\n \n            return `<a href=\"#\"\n                onclick=\"openPage(decodeURIComponent('${encoded}'));return false;\">${title}</a>`;\n        }\n    );\n \n    safe = safe.replace(/\\*\\*(.*?)\\*\\*/g, \"<strong>$1</strong>\");\n    safe = safe.replace(/\\*(.*?)\\*/g, \"<em>$1</em>\");\n \n    return safe;\n}\n \n// 렌더 후 이미지 src 채우기 (HTML 문자열 안에 큰 데이터 넣지 않기 위함)\nfunction hydrateImages(root) {\n    root.querySelectorAll(\"img[data-img]\").forEach(img => {\n        const src = images[img.dataset.img];\n        if (src) {\n            img.src = src;\n            img.onclick = () => openLightbox(src);\n        }\n    });\n}\n \n// ==========================================\n// 6. 문서 열기\n// ==========================================\n \nlet currentPage = \"\";\n \nfunction openPage(title) {\n \n    currentPage = title;\n \n    if (!pages[title]) {\n \n        pages[title] = {\n            title: title,\n            content:\n`# ${title}\n \n이 문서는 아직 작성되지 않았습니다.\n \n[편집] 버튼을 눌러 내용을 작성해 보세요.`,\n            updated: Date.now()\n        };\n \n        saveData();\n    }\n \n    renderPage();\n    window.scrollTo({ top: 0 });\n}\n \nfunction renderPage() {\n \n    const page = pages[currentPage];\n \n    if (!page) return;\n \n    const main = document.getElementById(\"main\");\n \n    main.innerHTML = `\n \n        <h1 class=\"title\">${escapeHTML(page.title)}</h1>\n \n        <div class=\"tabs\">\n            <button class=\"active\" onclick=\"renderPage()\">문서</button>\n            <button onclick=\"editPage()\">편집</button>\n            <button onclick=\"showHistory()\">역사</button>\n            <button onclick=\"showDiscussion()\">토론${(comments[currentPage] || []).length ? \" (\" + comments[currentPage].length + \")\" : \"\"}</button>\n        </div>\n \n        <div class=\"info-box\">\n            <h3>KnHCommunity 문서</h3>\n            이 문서는 KnHCommunity에서 관리됩니다.\n        </div>\n \n        <div class=\"content\">\n            ${renderWiki(page.content)}\n        </div>\n \n        <hr>\n \n        <p class=\"status\">\n            최근 수정: ${new Date(page.updated).toLocaleString()}\n        </p>\n    `;\n \n    hydrateImages(main);\n}\n \n// ==========================================\n// 7. 문서 편집\n// ==========================================\n \nfunction editPage() {\n \n    const page = pages[currentPage];\n \n    document.getElementById(\"main\").innerHTML = `\n \n        <h1 class=\"title\">문서 편집</h1>\n \n        <div class=\"label\">문서 제목</div>\n        <input id=\"editTitle\" class=\"edit-title\" value=\"${escapeHTML(page.title)}\">\n \n        <div class=\"label\">문서 내용</div>\n \n        <div class=\"toolbar\">\n            <button class=\"img-btn\" onclick=\"pickImages()\">🖼 이미지 첨부</button>\n            <button onclick=\"wrapSel('**','**')\"><b>B</b></button>\n            <button onclick=\"wrapSel('*','*')\"><i>I</i></button>\n            <button onclick=\"wrapSel('[[',']]')\">링크</button>\n            <button onclick=\"prefixLine('## ')\">소제목</button>\n            <button onclick=\"prefixLine('- ')\">목록</button>\n            <button onclick=\"insertText('\\\\n[목차]\\\\n')\">목차</button>\n        </div>\n \n        <textarea id=\"editContent\" class=\"editor\">${escapeHTML(page.content)}</textarea>\n \n        <p class=\"dropzone-hint\">\n            💡 이미지를 이 입력창에 드래그하거나 Ctrl+V로 붙여넣을 수도 있습니다.\n        </p>\n \n        <div class=\"label\">첨부된 이미지</div>\n        <div class=\"attachments\" id=\"attachments\"></div>\n \n        <p class=\"status\">\n            사용 가능한 문법:\n            # 제목 / ## 소제목 / [[문서명]] / **굵게** / *기울임* /\n            [목차] / - 목록 / ![설명](img:ID)\n        </p>\n \n        <button class=\"action\" onclick=\"savePage()\">저장</button>\n        <button class=\"secondary\" onclick=\"cancelEdit()\">취소</button>\n    `;\n \n    const area = document.getElementById(\"editContent\");\n \n    area.addEventListener(\"input\", refreshAttachments);\n \n    area.addEventListener(\"dragover\", e => {\n        e.preventDefault();\n        area.classList.add(\"dragover\");\n    });\n \n    area.addEventListener(\"dragleave\", () => area.classList.remove(\"dragover\"));\n \n    area.addEventListener(\"drop\", e => {\n        e.preventDefault();\n        area.classList.remove(\"dragover\");\n        addImageFiles(Array.from(e.dataTransfer.files));\n    });\n \n    area.addEventListener(\"paste\", e => {\n        const files = Array.from(e.clipboardData.files || [])\n            .filter(f => f.type.startsWith(\"image/\"));\n \n        if (files.length) {\n            e.preventDefault();\n            addImageFiles(files);\n        }\n    });\n \n    refreshAttachments();\n}\n \nfunction wrapSel(before, after) {\n    const a = document.getElementById(\"editContent\");\n    const s = a.selectionStart, e = a.selectionEnd;\n    const sel = a.value.slice(s, e) || \"텍스트\";\n    a.value = a.value.slice(0, s) + before + sel + after + a.value.slice(e);\n    a.focus();\n    a.selectionStart = s + before.length;\n    a.selectionEnd = s + before.length + sel.length;\n}\n \nfunction prefixLine(prefix) {\n    const a = document.getElementById(\"editContent\");\n    const s = a.selectionStart;\n    const lineStart = a.value.lastIndexOf(\"\\n\", s - 1) + 1;\n    a.value = a.value.slice(0, lineStart) + prefix + a.value.slice(lineStart);\n    a.focus();\n}\n \nfunction insertText(t) {\n    insertAtCursor(document.getElementById(\"editContent\"), t);\n}\n \nfunction cancelEdit() {\n    // 편집 중 추가했지만 저장하지 않은 이미지 정리\n    images = load(IMAGE_KEY, {});\n    renderPage();\n}\n \nfunction savePage() {\n \n    const newTitle = document.getElementById(\"editTitle\").value.trim();\n    const newContent = document.getElementById(\"editContent\").value;\n \n    if (!newTitle) {\n        alert(\"문서 제목을 입력하세요.\");\n        return;\n    }\n \n    if (!newContent.trim()) {\n        alert(\"문서 내용을 입력하세요.\");\n        return;\n    }\n \n    const oldTitle = currentPage;\n \n    if (newTitle !== oldTitle && pages[newTitle]) {\n        alert(\"이미 존재하는 문서 제목입니다.\");\n        return;\n    }\n \n    delete pages[oldTitle];\n \n    // 문서 제목이 바뀌면 토론도 같이 이동\n    if (newTitle !== oldTitle && comments[oldTitle]) {\n        comments[newTitle] = comments[oldTitle];\n        delete comments[oldTitle];\n    }\n \n    pages[newTitle] = {\n        title: newTitle,\n        content: newContent,\n        updated: Date.now()\n    };\n \n    currentPage = newTitle;\n \n    cleanupImages();\n \n    if (!saveData()) return;\n \n    renderPage();\n    toast(\"문서가 저장되었습니다!\");\n}\n \n// ==========================================\n// 8. 새 문서 만들기\n// ==========================================\n \nfunction createPage() {\n \n    const title = uniqueTitle(\"새 문서\");\n \n    currentPage = title;\n \n    pages[title] = {\n        title: title,\n        content: `# ${title}\\n\\n내용을 입력하세요.`,\n        updated: Date.now()\n    };\n \n    saveData();\n    editPage();\n}\n \n// ==========================================\n// 9. 대문\n// ==========================================\n \nfunction home() {\n \n    document.getElementById(\"main\").innerHTML = `\n \n        <h1 class=\"title\">KnHCommunity 대문</h1>\n \n        <div class=\"info-box\">\n            <h3>KnHCommunity에 오신 것을 환영합니다!</h3>\n            친구들과 함께 만드는 우리만의 위키 커뮤니티입니다.\n        </div>\n \n        <h2 class=\"main-h2\">📢 공지사항</h2>\n        <p>KnHCommunity 서비스가 시작되었습니다! 이제 이미지 첨부, 테마 설정, Discord 스타일 토론을 사용할 수 있어요.</p>\n \n        <h2 class=\"main-h2\">📚 전체 문서</h2>\n        <ul class=\"page-list\" id=\"homePages\"></ul>\n \n        <h2 class=\"main-h2\">🕒 최근 변경</h2>\n        <ul class=\"page-list\" id=\"homeRecent\"></ul>\n \n        <button class=\"action\" onclick=\"createPage()\">새 문서 만들기</button>\n    `;\n \n    const list = document.getElementById(\"homePages\");\n \n    Object.keys(pages).forEach(title => {\n \n        const li = document.createElement(\"li\");\n        const a = document.createElement(\"a\");\n \n        a.href = \"#\";\n        a.textContent = title;\n        a.onclick = () => { openPage(title); return false; };\n \n        li.appendChild(a);\n        li.onclick = () => openPage(title);\n        list.appendChild(li);\n    });\n \n    const recent = Object.keys(pages)\n        .sort((a, b) => pages[b].updated - pages[a].updated)\n        .slice(0, 5);\n \n    const recentList = document.getElementById(\"homeRecent\");\n \n    recent.forEach(title => {\n \n        const li = document.createElement(\"li\");\n        li.innerHTML = `${escapeHTML(title)}<span class=\"sub\">${new Date(pages[title].updated).toLocaleString()}</span>`;\n        li.onclick = () => openPage(title);\n \n        recentList.appendChild(li);\n    });\n}\n \n// ==========================================\n// 10. 전체 문서\n// ==========================================\n \nfunction allPages() {\n \n    document.getElementById(\"main\").innerHTML = `\n        <h1 class=\"title\">전체 문서</h1>\n        <ul class=\"page-list\" id=\"allPages\"></ul>\n    `;\n \n    const list = document.getElementById(\"allPages\");\n \n    Object.keys(pages).sort().forEach(title => {\n \n        const li = document.createElement(\"li\");\n        li.textContent = title;\n        li.onclick = () => openPage(title);\n \n        list.appendChild(li);\n    });\n}\n \n// ==========================================\n// 11. 문서 검색\n// ==========================================\n \nfunction searchPage() {\n \n    const query = document.getElementById(\"search\").value.trim();\n \n    if (!query) return;\n \n    const q = query.toLowerCase();\n \n    const results = Object.keys(pages).filter(title =>\n        title.toLowerCase().includes(q) ||\n        pages[title].content.toLowerCase().includes(q)\n    );\n \n    document.getElementById(\"main\").innerHTML = `\n        <h1 class=\"title\">검색 결과</h1>\n        <p>검색어: <b>${escapeHTML(query)}</b> (${results.length}건)</p>\n        <ul class=\"page-list\" id=\"searchResults\"></ul>\n    `;\n \n    const list = document.getElementById(\"searchResults\");\n \n    results.forEach(title => {\n \n        const li = document.createElement(\"li\");\n        li.textContent = title;\n        li.onclick = () => openPage(title);\n \n        list.appendChild(li);\n    });\n \n    if (results.length === 0) {\n        list.innerHTML = \"<p class='status'>검색 결과가 없습니다.</p>\";\n    }\n}\n \n// ==========================================\n// 12. 최근 변경\n// ==========================================\n \nfunction recentChanges() {\n \n    const sorted = Object.keys(pages).sort(\n        (a, b) => pages[b].updated - pages[a].updated\n    );\n \n    document.getElementById(\"main\").innerHTML = `\n        <h1 class=\"title\">최근 변경</h1>\n        <ul class=\"page-list\" id=\"recentList\"></ul>\n    `;\n \n    const list = document.getElementById(\"recentList\");\n \n    sorted.forEach(title => {\n \n        const li = document.createElement(\"li\");\n \n        li.innerHTML = `${escapeHTML(title)}<span class=\"sub\">${new Date(pages[title].updated).toLocaleString()}</span>`;\n        li.onclick = () => openPage(title);\n \n        list.appendChild(li);\n    });\n}\n \n// ==========================================\n// 13. 역사 / 토론 (다음 단계에서 구현)\n// ==========================================\n \nfunction showHistory() {\n \n    document.getElementById(\"main\").innerHTML = `\n        <h1 class=\"title\">문서 역사</h1>\n        <p>문서 수정 기록 기능은 STEP 3에서 구현합니다.</p>\n        <button class=\"action\" onclick=\"renderPage()\">돌아가기</button>\n    `;\n}\n \n// ------------------------------------------\n// 토론 (Discord 스타일 댓글)\n// ------------------------------------------\n \nconst EMOJI_LIST = [\n    \"👍\", \"❤️\", \"😂\", \"😮\", \"😢\", \"🎉\",\n    \"🔥\", \"👀\", \"🙏\", \"👏\", \"😍\", \"🤔\",\n    \"😎\", \"💯\", \"✅\", \"❌\", \"🥲\", \"😭\",\n    \"😡\", \"🤝\", \"💀\", \"✨\", \"🍀\", \"🎮\"\n];\n \nconst NAME_COLORS = [\n    \"#f47fff\", \"#5ec4ff\", \"#57f287\", \"#fee75c\",\n    \"#ff9f6b\", \"#b79cff\", \"#ff7b7b\", \"#4ee3c1\"\n];\n \nlet me = load(USER_KEY, null);\n \nif (!me || !me.id) {\n    me = {\n        id: \"u\" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),\n        name: \"익명\" + (100 + Math.floor(Math.random() * 900))\n    };\n    saveMe();\n}\n \nfunction saveMe() {\n    try { localStorage.setItem(USER_KEY, JSON.stringify(me)); } catch (e) {}\n}\n \nlet replyTo = null;\nlet pendingImgs = [];\nlet editingId = null;\n \nfunction colorFor(key) {\n    let h = 0;\n    for (const c of String(key)) h = (h * 31 + c.charCodeAt(0)) >>> 0;\n    return NAME_COLORS[h % NAME_COLORS.length];\n}\n \nfunction findMsg(id) {\n    return (comments[currentPage] || []).find(m => m.id === id);\n}\n \nfunction unescapeHTML(s) {\n    return s.replace(/&lt;/g, \"<\").replace(/&gt;/g, \">\")\n            .replace(/&quot;/g, '\"').replace(/&#39;/g, \"'\")\n            .replace(/&amp;/g, \"&\");\n}\n \nfunction timeLabel(ts) {\n    return new Date(ts).toLocaleTimeString(\"ko-KR\", { hour: \"numeric\", minute: \"2-digit\" });\n}\n \nfunction fullTimeLabel(ts) {\n    const d = new Date(ts), now = new Date();\n    const y = new Date(now);\n    y.setDate(now.getDate() - 1);\n \n    if (d.toDateString() === now.toDateString()) return \"오늘 \" + timeLabel(ts);\n    if (d.toDateString() === y.toDateString()) return \"어제 \" + timeLabel(ts);\n    return d.toLocaleDateString(\"ko-KR\") + \" \" + timeLabel(ts);\n}\n \nfunction dateLabel(ts) {\n    return new Date(ts).toLocaleDateString(\"ko-KR\", {\n        year: \"numeric\", month: \"long\", day: \"numeric\", weekday: \"long\"\n    });\n}\n \n// 댓글용 가벼운 문법: **굵게** *기울임* ~~취소선~~ `코드` [[문서]] @멘션\nfunction formatChat(text) {\n \n    let s = escapeHTML(text);\n \n    s = s.replace(/`([^`\\n]+)`/g, \"<code>$1</code>\");\n    s = s.replace(/\\*\\*(.+?)\\*\\*/g, \"<strong>$1</strong>\");\n    s = s.replace(/\\*(.+?)\\*/g, \"<em>$1</em>\");\n    s = s.replace(/~~(.+?)~~/g, \"<s>$1</s>\");\n \n    s = s.replace(/\\[\\[(.+?)\\]\\]/g, (m, t) => {\n        const enc = encodeURIComponent(unescapeHTML(t)).replace(/'/g, \"%27\");\n        return `<a href=\"#\" onclick=\"openPage(decodeURIComponent('${enc}'));return false;\">${t}</a>`;\n    });\n \n    s = s.replace(/(^|\\s)@([\\w가-힣]+)/g, '$1<span class=\"mention\">@$2</span>');\n \n    return s.replace(/\\n/g, \"<br>\");\n}\n \nfunction showDiscussion() {\n \n    const page = pages[currentPage];\n    if (!page) return;\n \n    replyTo = null;\n    pendingImgs = [];\n    editingId = null;\n \n    const safeTitle = escapeHTML(page.title);\n \n    document.getElementById(\"main\").innerHTML = `\n \n        <h1 class=\"title\">${safeTitle}</h1>\n \n        <div class=\"tabs\">\n            <button onclick=\"renderPage()\">문서</button>\n            <button onclick=\"editPage()\">편집</button>\n            <button onclick=\"showHistory()\">역사</button>\n            <button class=\"active\" onclick=\"showDiscussion()\">토론</button>\n        </div>\n \n        <div class=\"chat\">\n \n            <div class=\"chat-head\">\n                <span class=\"hash\">#</span> 토론\n                <span class=\"chat-sub\">${safeTitle} 문서에 대한 이야기를 나눠보세요</span>\n                <span class=\"chat-count\" id=\"chatCount\"></span>\n            </div>\n \n            <div class=\"chat-body\" id=\"chatBody\"></div>\n \n            <div class=\"chat-compose\">\n \n                <div class=\"reply-bar\" id=\"replyBar\" hidden></div>\n                <div class=\"pending\" id=\"pendingImgs\"></div>\n \n                <div class=\"compose-box\">\n                    <button class=\"c-btn\" title=\"이미지 첨부\" onclick=\"pickChatImages()\">＋</button>\n                    <textarea id=\"chatInput\" rows=\"1\"\n                        placeholder=\"#${safeTitle}에 메시지 보내기\"></textarea>\n                    <button class=\"c-btn\" title=\"이모지\"\n                        onclick=\"event.stopPropagation(); openEmojiPicker(this, insertEmoji)\">😊</button>\n                    <button class=\"c-send\" onclick=\"sendMessage()\">전송</button>\n                </div>\n \n                <div class=\"who\">\n                    내 닉네임: <b id=\"meName\"></b>\n                    <a onclick=\"changeName()\">변경</a>\n                    · Enter 전송 / Shift+Enter 줄바꿈\n                </div>\n \n            </div>\n        </div>\n    `;\n \n    document.getElementById(\"meName\").textContent = me.name;\n \n    bindChat();\n    renderMessages(true);\n}\n \nfunction bindChat() {\n \n    const chat = document.querySelector(\".chat\");\n    const body = document.getElementById(\"chatBody\");\n    const input = document.getElementById(\"chatInput\");\n \n    // 메시지 영역 클릭 (이벤트 위임)\n    body.addEventListener(\"click\", e => {\n \n        const img = e.target.closest(\"img[data-img]\");\n \n        if (img && images[img.dataset.img]) {\n            openLightbox(images[img.dataset.img]);\n            return;\n        }\n \n        const el = e.target.closest(\"[data-act]\");\n        if (!el) return;\n \n        const id = el.dataset.id;\n \n        switch (el.dataset.act) {\n            case \"react\":\n                toggleReaction(id, el.dataset.emoji);\n                break;\n            case \"pick\":\n                e.stopPropagation();\n                openEmojiPicker(el, emoji => toggleReaction(id, emoji));\n                break;\n            case \"reply\":\n                startReply(id);\n                break;\n            case \"edit\":\n                startEdit(id);\n                break;\n            case \"delete\":\n                deleteMessage(id);\n                break;\n            case \"jump\":\n                jumpTo(id);\n                break;\n            case \"mention\":\n                insertEmoji(\"@\" + el.dataset.name + \" \");\n                break;\n        }\n    });\n \n    // 메시지 수정 입력\n    body.addEventListener(\"keydown\", e => {\n \n        if (e.target.id !== \"editMsg\") return;\n \n        if (e.key === \"Enter\" && !e.shiftKey && !e.isComposing) {\n            e.preventDefault();\n            saveEdit(e.target.dataset.id);\n        }\n        else if (e.key === \"Escape\") {\n            editingId = null;\n            renderMessages(false);\n        }\n    });\n \n    // 입력창\n    input.addEventListener(\"keydown\", e => {\n \n        if (e.key === \"Enter\" && !e.shiftKey && !e.isComposing) {\n            e.preventDefault();\n            sendMessage();\n        }\n        else if (e.key === \"Escape\" && replyTo) {\n            cancelReply();\n        }\n    });\n \n    input.addEventListener(\"input\", () => autoGrow(input));\n \n    input.addEventListener(\"paste\", e => {\n        const files = Array.from(e.clipboardData.files || [])\n            .filter(f => f.type.startsWith(\"image/\"));\n \n        if (files.length) {\n            e.preventDefault();\n            addChatImages(files);\n        }\n    });\n \n    // 드래그 앤 드롭\n    chat.addEventListener(\"dragover\", e => {\n        e.preventDefault();\n        chat.classList.add(\"dragover\");\n    });\n \n    chat.addEventListener(\"dragleave\", e => {\n        if (!chat.contains(e.relatedTarget)) chat.classList.remove(\"dragover\");\n    });\n \n    chat.addEventListener(\"drop\", e => {\n        e.preventDefault();\n        chat.classList.remove(\"dragover\");\n        addChatImages(Array.from(e.dataTransfer.files));\n    });\n}\n \nfunction autoGrow(el) {\n    el.style.height = \"auto\";\n    el.style.height = Math.min(el.scrollHeight, 160) + \"px\";\n}\n \nfunction insertEmoji(text) {\n    const input = document.getElementById(\"chatInput\");\n    if (!input) return;\n    insertAtCursor(input, text);\n    autoGrow(input);\n}\n \n// ---------- 메시지 렌더링 ----------\n \nfunction replyRefHTML(id) {\n \n    const o = findMsg(id);\n \n    if (!o) {\n        return `<div class=\"reply-ref deleted\">↪ 원본 메시지가 삭제되었습니다</div>`;\n    }\n \n    const preview = o.text ? escapeHTML(o.text.slice(0, 60)) : \"🖼 이미지\";\n \n    return `<div class=\"reply-ref\" data-act=\"jump\" data-id=\"${id}\">\n        ↪ <b style=\"color:${colorFor(o.uid)}\">${escapeHTML(o.name)}</b>\n        <span>${preview}</span>\n    </div>`;\n}\n \nfunction messageHTML(m, grouped) {\n \n    const mine = m.uid === me.id;\n    const mentioned = !mine && m.text.includes(\"@\" + me.name);\n \n    const reactions = Object.entries(m.reactions || {})\n        .filter(([, users]) => users.length)\n        .map(([emoji, users]) =>\n            `<button class=\"react ${users.includes(me.id) ? \"mine\" : \"\"}\"\n                data-act=\"react\" data-id=\"${m.id}\" data-emoji=\"${emoji}\">\n                ${emoji} <span>${users.length}</span>\n            </button>`\n        ).join(\"\");\n \n    const addBtn = reactions\n        ? `<button class=\"react add\" data-act=\"pick\" data-id=\"${m.id}\" title=\"반응 추가\">😀＋</button>`\n        : \"\";\n \n    const imgs = (m.imgs || []).map(id =>\n        images[id]\n            ? `<img class=\"chat-img\" data-img=\"${id}\" alt=\"첨부 이미지\">`\n            : `<span class=\"broken-img\">🖼 이미지를 찾을 수 없습니다</span>`\n    ).join(\"\");\n \n    let body;\n \n    if (editingId === m.id) {\n        body = `<div class=\"edit-box\">\n            <textarea id=\"editMsg\" data-id=\"${m.id}\">${escapeHTML(m.text)}</textarea>\n            <div class=\"edit-hint\">Esc 취소 · Enter 저장</div>\n        </div>`;\n    } else {\n        body = m.text\n            ? `<div class=\"msg-text\">${formatChat(m.text)}${m.edited ? '<span class=\"edited\">(수정됨)</span>' : \"\"}</div>`\n            : \"\";\n    }\n \n    const initial = Array.from(m.name)[0] || \"?\";\n \n    const left = grouped\n        ? `<span class=\"hover-time\">${timeLabel(m.time)}</span>`\n        : `<div class=\"avatar\" style=\"background:${colorFor(m.uid)}\"\n              data-act=\"mention\" data-name=\"${escapeHTML(m.name)}\"\n              title=\"멘션하기\">${escapeHTML(initial)}</div>`;\n \n    const meta = grouped ? \"\" : `\n        <div class=\"msg-meta\">\n            <span class=\"msg-name\" style=\"color:${colorFor(m.uid)}\"\n                data-act=\"mention\" data-name=\"${escapeHTML(m.name)}\">${escapeHTML(m.name)}</span>\n            <span class=\"msg-time\">${fullTimeLabel(m.time)}</span>\n        </div>`;\n \n    const tools = `\n        <div class=\"msg-tools\">\n            <button data-act=\"pick\" data-id=\"${m.id}\" title=\"반응 추가\">😀</button>\n            <button data-act=\"reply\" data-id=\"${m.id}\" title=\"답장\">↩</button>\n            ${mine ? `<button data-act=\"edit\" data-id=\"${m.id}\" title=\"수정\">✏️</button>\n                      <button class=\"danger\" data-act=\"delete\" data-id=\"${m.id}\" title=\"삭제\">🗑</button>` : \"\"}\n        </div>`;\n \n    return `\n        <div class=\"msg ${grouped ? \"grouped\" : \"\"} ${mentioned ? \"mentioned\" : \"\"}\" id=\"msg-${m.id}\">\n            ${m.replyTo ? replyRefHTML(m.replyTo) : \"\"}\n            <div class=\"msg-row\">\n                <div class=\"msg-left\">${left}</div>\n                <div class=\"msg-main\">\n                    ${meta}\n                    ${body}\n                    ${imgs}\n                    ${reactions ? `<div class=\"reactions\">${reactions}${addBtn}</div>` : \"\"}\n                </div>\n            </div>\n            ${editingId === m.id ? \"\" : tools}\n        </div>`;\n}\n \nfunction renderMessages(stick = true) {\n \n    const body = document.getElementById(\"chatBody\");\n    if (!body) return;\n \n    const list = comments[currentPage] || [];\n    const top = body.scrollTop;\n \n    document.getElementById(\"chatCount\").textContent = list.length + \"개의 메시지\";\n \n    if (!list.length) {\n        body.innerHTML = `\n            <div class=\"chat-empty\">\n                <div class=\"big\">💬</div>\n                <b>아직 토론이 없어요</b>\n                첫 메시지를 남겨 대화를 시작해 보세요!\n            </div>`;\n        return;\n    }\n \n    let html = \"\";\n    let prev = null;\n \n    list.forEach(m => {\n \n        if (!prev || new Date(prev.time).toDateString() !== new Date(m.time).toDateString()) {\n            html += `<div class=\"day-div\"><span>${dateLabel(m.time)}</span></div>`;\n            prev = null;\n        }\n \n        const grouped = prev && prev.uid === m.uid && !m.replyTo\n            && (m.time - prev.time) < 5 * 60 * 1000;\n \n        html += messageHTML(m, grouped);\n        prev = m;\n    });\n \n    body.innerHTML = html;\n \n    body.querySelectorAll(\"img[data-img]\").forEach(img => {\n        img.src = images[img.dataset.img];\n        img.onload = () => { if (stick) body.scrollTop = body.scrollHeight; };\n    });\n \n    body.scrollTop = stick ? body.scrollHeight : top;\n \n    if (editingId) {\n        const t = document.getElementById(\"editMsg\");\n        if (t) {\n            t.focus();\n            t.setSelectionRange(t.value.length, t.value.length);\n        }\n    }\n}\n \n// ---------- 메시지 동작 ----------\n \nfunction sendMessage() {\n \n    const input = document.getElementById(\"chatInput\");\n    if (!input) return;\n \n    const text = input.value.trim();\n \n    if (!text && !pendingImgs.length) return;\n \n    const list = comments[currentPage] = comments[currentPage] || [];\n \n    const msg = {\n        id: \"m\" + Date.now().toString(36) + Math.random().toString(36).slice(2, 5),\n        uid: me.id,\n        name: me.name,\n        text: text,\n        time: Date.now(),\n        edited: false,\n        replyTo: replyTo,\n        reactions: {},\n        imgs: pendingImgs.slice()\n    };\n \n    list.push(msg);\n \n    if (!saveData()) {\n        list.pop();\n        return;\n    }\n \n    pendingImgs = [];\n    replyTo = null;\n    input.value = \"\";\n    autoGrow(input);\n \n    renderPending();\n    renderReplyBar();\n    renderMessages(true);\n    input.focus();\n}\n \nfunction toggleReaction(id, emoji) {\n \n    const m = findMsg(id);\n    if (!m) return;\n \n    m.reactions = m.reactions || {};\n \n    const arr = m.reactions[emoji] = m.reactions[emoji] || [];\n    const i = arr.indexOf(me.id);\n \n    if (i >= 0) arr.splice(i, 1);\n    else arr.push(me.id);\n \n    if (!arr.length) delete m.reactions[emoji];\n \n    saveData();\n    renderMessages(false);\n}\n \nfunction startReply(id) {\n    replyTo = id;\n    renderReplyBar();\n    document.getElementById(\"chatInput\").focus();\n}\n \nfunction cancelReply() {\n    replyTo = null;\n    renderReplyBar();\n}\n \nfunction renderReplyBar() {\n \n    const bar = document.getElementById(\"replyBar\");\n    if (!bar) return;\n \n    const m = replyTo ? findMsg(replyTo) : null;\n \n    if (!m) {\n        replyTo = null;\n        bar.hidden = true;\n        bar.innerHTML = \"\";\n        return;\n    }\n \n    bar.hidden = false;\n    bar.innerHTML = `\n        <span><b style=\"color:${colorFor(m.uid)}\">${escapeHTML(m.name)}</b>님에게 답장하는 중</span>\n        <button onclick=\"cancelReply()\" title=\"취소\">✕</button>`;\n}\n \nfunction startEdit(id) {\n    editingId = id;\n    renderMessages(false);\n}\n \nfunction saveEdit(id) {\n \n    const m = findMsg(id);\n    const t = document.getElementById(\"editMsg\");\n \n    if (!m || !t) return;\n \n    const text = t.value.trim();\n \n    if (!text && !(m.imgs || []).length) {\n        toast(\"내용을 입력하세요. (삭제하려면 🗑 버튼)\");\n        return;\n    }\n \n    if (text !== m.text) {\n        m.text = text;\n        m.edited = true;\n        saveData();\n    }\n \n    editingId = null;\n    renderMessages(false);\n}\n \nfunction deleteMessage(id) {\n \n    if (!confirm(\"이 메시지를 삭제할까요?\")) return;\n \n    const list = comments[currentPage] || [];\n    const i = list.findIndex(m => m.id === id);\n \n    if (i < 0) return;\n \n    list.splice(i, 1);\n \n    if (replyTo === id) replyTo = null;\n \n    cleanupImages();\n    saveData();\n \n    renderReplyBar();\n    renderMessages(false);\n}\n \nfunction jumpTo(id) {\n \n    const el = document.getElementById(\"msg-\" + id);\n    if (!el) return;\n \n    el.scrollIntoView({ block: \"center\" });\n    el.classList.add(\"flash\");\n \n    setTimeout(() => el.classList.remove(\"flash\"), 1700);\n}\n \nfunction changeName() {\n \n    const n = prompt(\"사용할 닉네임을 입력하세요. (최대 16자)\", me.name);\n \n    if (n && n.trim()) {\n        me.name = n.trim().slice(0, 16);\n        saveMe();\n        document.getElementById(\"meName\").textContent = me.name;\n        toast(\"닉네임이 변경되었습니다.\");\n    }\n}\n \n// ---------- 댓글 이미지 첨부 ----------\n \nfunction pickChatImages() {\n    const input = document.getElementById(\"fileInput\");\n    input.value = \"\";\n    input.onchange = () => addChatImages(Array.from(input.files));\n    input.click();\n}\n \nasync function addChatImages(files) {\n \n    for (const file of files) {\n \n        if (!file.type.startsWith(\"image/\")) {\n            toast(\"이미지 파일만 첨부할 수 있습니다.\");\n            continue;\n        }\n \n        if (pendingImgs.length >= 4) {\n            toast(\"이미지는 한 번에 최대 4장까지 첨부할 수 있습니다.\");\n            break;\n        }\n \n        try {\n            const data = await compressImage(file, 960);\n            const id = newImageId();\n            images[id] = data;\n            pendingImgs.push(id);\n        } catch (e) {\n            toast(\"이미지를 불러오지 못했습니다.\");\n        }\n    }\n \n    renderPending();\n}\n \nfunction renderPending() {\n \n    const box = document.getElementById(\"pendingImgs\");\n    if (!box) return;\n \n    box.innerHTML = \"\";\n \n    pendingImgs.forEach(id => {\n \n        const item = document.createElement(\"div\");\n        item.className = \"pending-item\";\n \n        const img = document.createElement(\"img\");\n        img.src = images[id];\n        img.alt = \"\";\n \n        const del = document.createElement(\"button\");\n        del.textContent = \"✕\";\n        del.onclick = () => {\n            pendingImgs = pendingImgs.filter(x => x !== id);\n            delete images[id];\n            renderPending();\n        };\n \n        item.appendChild(img);\n        item.appendChild(del);\n        box.appendChild(item);\n    });\n}\n \n// ---------- 이모지 선택기 ----------\n \nfunction openEmojiPicker(anchor, callback) {\n \n    const pop = document.getElementById(\"emojiPop\");\n \n    pop.innerHTML = \"\";\n \n    EMOJI_LIST.forEach(emoji => {\n        const b = document.createElement(\"button\");\n        b.textContent = emoji;\n        b.onclick = e => {\n            e.stopPropagation();\n            callback(emoji);\n            closeEmojiPicker();\n        };\n        pop.appendChild(b);\n    });\n \n    pop.classList.add(\"show\");\n \n    const r = anchor.getBoundingClientRect();\n    const w = pop.offsetWidth;\n    const h = pop.offsetHeight;\n \n    let left = Math.max(10, Math.min(r.left, window.innerWidth - w - 10));\n    let topPos = r.bottom + 6;\n \n    if (topPos + h > window.innerHeight - 10) {\n        topPos = Math.max(10, r.top - h - 6);\n    }\n \n    pop.style.left = left + \"px\";\n    pop.style.top = topPos + \"px\";\n}\n \nfunction closeEmojiPicker() {\n    document.getElementById(\"emojiPop\").classList.remove(\"show\");\n}\n \ndocument.addEventListener(\"click\", e => {\n    const pop = document.getElementById(\"emojiPop\");\n    if (!pop.contains(e.target)) closeEmojiPicker();\n});\n \n// ==========================================\n// 14. 즐겨찾기\n// ==========================================\n \nconst favoritePages = [\"KnHCommunity\", \"사용자:주호\"];\n \nfunction renderFavorites() {\n \n    const area = document.getElementById(\"favorites\");\n \n    favoritePages.forEach(title => {\n \n        const a = document.createElement(\"a\");\n \n        a.textContent = \"★ \" + title;\n        a.onclick = () => openPage(title);\n \n        area.appendChild(a);\n    });\n}\n \n// ==========================================\n// 프로그램 시작\n// ==========================================\n \ndocument.addEventListener(\"keydown\", e => {\n    if (e.key === \"Escape\") {\n        closeSettings();\n        closeEmojiPicker();\n        document.getElementById(\"lightbox\").classList.remove(\"show\");\n    }\n});\n \napplySettings();\nrenderFavorites();\nhome();\n \n\n\n// ==========================================\n// 15. Cloudflare 자유게시판 / 회원 인증\n// ==========================================\n// 배포 후 본인의 Worker 주소로 반드시 변경하세요.\nconst KNH_API_BASE = \"https://knhcommunity-api.luckykjh0428.workers.dev\";\nlet knhAuthUser = null;\nlet knhBoardPage = 1;\nlet knhBoardQuery = \"\";\nlet knhBoardSort = \"latest\";\nlet knhEditingPost = null;\n\nasync function knhApi(path, options = {}) {\n    if (KNH_API_BASE.includes(\"YOUR-WORKER-NAME\")) {\n        throw new Error(\"아직 Worker 주소가 설정되지 않았습니다. index.html의 KNH_API_BASE를 변경해 주세요.\");\n    }\n    const response = await fetch(KNH_API_BASE.replace(/\\/$/, \"\") + path, {\n        credentials: \"include\",\n        ...options,\n        headers: { \"Content-Type\": \"application/json\", ...(options.headers || {}) }\n    });\n    let data = {};\n    try { data = await response.json(); } catch (_) {}\n    if (!response.ok) throw new Error(data.error || `요청 실패 (${response.status})`);\n    return data;\n}\n\nasync function knhRefreshAuth() {\n    try {\n        const data = await knhApi(\"/api/auth/me\", { method: \"GET\", headers: {} });\n        knhAuthUser = data.user || null;\n    } catch (_) { knhAuthUser = null; }\n    return knhAuthUser;\n}\n\nfunction knhAuthBar() {\n    if (knhAuthUser) {\n        return `<div class=\"board-userbar\"><span>👤 <b>${escapeHTML(knhAuthUser.nickname)}</b>님 로그인 중</span><button class=\"board-btn secondary\" onclick=\"knhLogout()\">로그아웃</button></div>`;\n    }\n    return `<div class=\"board-userbar\"><span>게시글 작성과 댓글은 로그인이 필요합니다.</span><button class=\"board-btn secondary\" onclick=\"knhAuthScreen('login')\">로그인</button><button class=\"board-btn\" onclick=\"knhAuthScreen('register')\">회원가입</button></div>`;\n}\n\nasync function knhBoardHome(page = 1) {\n    knhBoardPage = page;\n    const main = document.getElementById(\"main\");\n main.innerHTML = `<div class=\"board-wrap\"><h1 class=\"title\">💬 자유게시판</h1><div class=\"board-top\"><div id=\"knh-auth-bar\"></div><div class=\"board-tools\"><input id=\"knh-board-search\" placeholder=\"제목 또는 내용 검색\" value=\"${escapeHTML(knhBoardQuery)}\" onkeydown=\"if(event.key==='Enter') knhSearchBoard()\"><button class=\"board-btn secondary\" onclick=\"knhSearchBoard()\">검색</button><select id=\"knh-board-sort\" onchange=\"knhChangeSort(this.value)\" style=\"padding:10px;border:1px solid var(--border);border-radius:10px;background:var(--surface-2);color:var(--text)\"><option value=\"latest\" ${knhBoardSort==='latest'?'selected':''}>최신순</option><option value=\"views\" ${knhBoardSort==='views'?'selected':''}>조회순</option></select></div></div><div id=\"knh-board-list\"><div class=\"board-empty\">게시글을 불러오는 중...</div></div></div>`;\n    await knhRefreshAuth();\n    document.getElementById(\"knh-auth-bar\").innerHTML = knhAuthBar();\n    await knhLoadPosts();\n}\n\nasync function knhLoadPosts() {\n    const list = document.getElementById(\"knh-board-list\");\n    if (!list) return;\n    list.innerHTML = `<div class=\"board-empty\">게시글을 불러오는 중...</div>`;\n    try {\n        const params = new URLSearchParams({ page: String(knhBoardPage), sort: knhBoardSort });\n        if (knhBoardQuery) params.set(\"q\", knhBoardQuery);\n        const data = await knhApi(\"/api/posts?\" + params.toString(), { method: \"GET\", headers: {} });\n        if (!data.posts.length) {\n            list.innerHTML = `<div class=\"board-empty\">아직 게시글이 없습니다.<br>첫 번째 글을 작성해 보세요!</div>`;\n        } else {\n            const rows = data.posts.map((post, i) => `<tr><td>${(data.page - 1) * data.limit + i + 1}</td><td><span class=\"board-title-link\" onclick=\"knhOpenPost('${post.id}')\">${escapeHTML(post.title)}</span> <span class=\"board-muted\">[${post.comment_count}]</span></td><td>${escapeHTML(post.author)}</td><td>${new Date(post.created_at).toLocaleDateString('ko-KR')}</td><td>${post.views}</td></tr>`).join(\"\");\n            list.innerHTML = `<table class=\"board-table\"><thead><tr><th style=\"width:55px\">번호</th><th>제목</th><th style=\"width:110px\">작성자</th><th style=\"width:120px\">날짜</th><th style=\"width:65px\">조회</th></tr></thead><tbody>${rows}</tbody></table><div class=\"board-pagination\"><button class=\"board-btn secondary\" ${data.page<=1?'disabled':''} onclick=\"knhBoardHome(${data.page-1})\">이전</button><span class=\"board-muted\">${data.page} / ${Math.max(1,data.pages)} 페이지 · 총 ${data.total}개</span><button class=\"board-btn secondary\" ${data.page>=data.pages?'disabled':''} onclick=\"knhBoardHome(${data.page+1})\">다음</button></div>`;\n        }\n        const write = document.createElement(\"div\");\n        write.className = \"board-top\";\n        write.style.justifyContent = \"flex-end\";\n        write.innerHTML = `<button class=\"board-btn\" onclick=\"knhAuthUser ? knhPostForm() : knhAuthScreen('login')\">✏️ 글쓰기</button>`;\n        list.appendChild(write);\n    } catch (error) {\n        list.innerHTML = `<div class=\"board-empty\">${escapeHTML(error.message)}<br><br><button class=\"board-btn secondary\" onclick=\"knhBoardHome(${knhBoardPage})\">다시 시도</button></div>`;\n    }\n}\n\nfunction knhSearchBoard() {\n    knhBoardQuery = document.getElementById(\"knh-board-search\")?.value.trim() || \"\";\n    knhBoardHome(1);\n}\nfunction knhChangeSort(value) { knhBoardSort = value; knhBoardHome(1); }\n\nfunction knhAuthScreen(mode = \"login\") {\n    const register = mode === \"register\";\n    document.getElementById(\"main\").innerHTML = `<h1 class=\"title\">${register ? '회원가입' : '로그인'}</h1><div class=\"board-auth\"><h2>${register ? 'KnHCommunity 계정 만들기' : 'KnHCommunity 로그인'}</h2><form onsubmit=\"knhSubmitAuth(event,'${mode}')\">${register ? `<label for=\"knh-nickname\">닉네임</label><input id=\"knh-nickname\" maxlength=\"16\" required placeholder=\"게시판에 표시될 닉네임\">` : ''}<label for=\"knh-username\">아이디</label><input id=\"knh-username\" minlength=\"4\" maxlength=\"20\" autocomplete=\"username\" required placeholder=\"영문·숫자·밑줄 4~20자\"><label for=\"knh-password\">비밀번호</label><input id=\"knh-password\" type=\"password\" minlength=\"10\" maxlength=\"72\" autocomplete=\"${register?'new-password':'current-password'}\" required placeholder=\"10자 이상\"><div id=\"knh-auth-error\" class=\"board-error\" role=\"alert\"></div><div class=\"board-auth-actions\"><button class=\"board-btn\" type=\"submit\">${register ? '가입하기' : '로그인'}</button><button class=\"board-btn secondary\" type=\"button\" onclick=\"knhBoardHome()\">취소</button></div></form><p class=\"board-muted\">${register ? '이미 계정이 있나요? ' : '계정이 없나요? '}<a href=\"#\" onclick=\"event.preventDefault();knhAuthScreen('${register?'login':'register'}')\">${register?'로그인':'회원가입'}</a></p><p class=\"board-muted\">비밀번호는 서버에서 PBKDF2 방식으로 해시되어 저장됩니다.</p></div>`;\n}\n\nasync function knhSubmitAuth(event, mode) {\n    event.preventDefault();\n    const errorBox = document.getElementById(\"knh-auth-error\");\n    const submit = event.target.querySelector('button[type=\"submit\"]');\n    submit.disabled = true;\n    errorBox.textContent = \"처리 중...\";\n    const body = {\n        username: document.getElementById(\"knh-username\").value.trim(),\n        password: document.getElementById(\"knh-password\").value\n    };\n    if (mode === \"register\") body.nickname = document.getElementById(\"knh-nickname\").value.trim();\n    try {\n        const data = await knhApi(mode === \"register\" ? \"/api/auth/register\" : \"/api/auth/login\", { method: \"POST\", body: JSON.stringify(body) });\n        knhAuthUser = data.user;\n        toast(mode === \"register\" ? \"회원가입이 완료되었습니다.\" : \"로그인되었습니다.\");\n        await knhBoardHome();\n    } catch (error) {\n        errorBox.textContent = error.message;\n        submit.disabled = false;\n    }\n}\n\nasync function knhLogout() {\n    try { await knhApi(\"/api/auth/logout\", { method: \"POST\", body: \"{}\" }); }\n    catch (error) { toast(error.message); }\n    knhAuthUser = null;\n    toast(\"로그아웃되었습니다.\");\n    await knhBoardHome();\n}\n\nfunction knhPostForm(post = null) {\n    if (!knhAuthUser) return knhAuthScreen(\"login\");\n    knhEditingPost = post ? post.id : null;\n    document.getElementById(\"main\").innerHTML = `<h1 class=\"title\">${post ? '게시글 수정' : '새 글 작성'}</h1><div class=\"board-form\"><label for=\"knh-post-title\">제목</label><input id=\"knh-post-title\" maxlength=\"100\" value=\"${post ? escapeHTML(post.title) : ''}\" placeholder=\"제목을 입력하세요\"><label for=\"knh-post-content\">내용</label><textarea id=\"knh-post-content\" maxlength=\"20000\" placeholder=\"내용을 입력하세요\">${post ? escapeHTML(post.content) : ''}</textarea><div class=\"board-top\"><span class=\"board-muted\">본문은 최대 20,000자까지 작성할 수 있습니다.</span><div><button class=\"board-btn secondary\" onclick=\"knhBoardHome()\">취소</button> <button class=\"board-btn\" onclick=\"knhSavePost()\">${post ? '수정 완료' : '등록하기'}</button></div></div><div id=\"knh-post-error\" class=\"board-error\"></div></div>`;\n}\n\nasync function knhSavePost() {\n    const title = document.getElementById(\"knh-post-title\").value.trim();\n    const content = document.getElementById(\"knh-post-content\").value.trim();\n    const error = document.getElementById(\"knh-post-error\");\n    try {\n        if (knhEditingPost) {\n            await knhApi(`/api/posts/${knhEditingPost}`, { method: \"PATCH\", body: JSON.stringify({ title, content }) });\n            toast(\"게시글이 수정되었습니다.\");\n            await knhOpenPost(knhEditingPost);\n        } else {\n            const data = await knhApi(\"/api/posts\", { method: \"POST\", body: JSON.stringify({ title, content }) });\n            toast(\"게시글이 등록되었습니다.\");\n            await knhOpenPost(data.id);\n        }\n    } catch (e) { error.textContent = e.message; }\n}\n\nasync function knhOpenPost(postId) {\n    const main = document.getElementById(\"main\");\n    main.innerHTML = `<div class=\"board-empty\">게시글을 불러오는 중...</div>`;\n    try {\n        await knhRefreshAuth();\n        const data = await knhApi(`/api/posts/${postId}`, { method: \"GET\", headers: {} });\n        const p = data.post;\n        window.knhEditPostData = { id: p.id, title: p.title, content: p.content };\n        const controls = p.mine ? `<button class=\"board-btn secondary\" onclick=\"knhPostForm(window.knhEditPostData)\">수정</button> <button class=\"board-btn danger\" onclick=\"knhDeletePost('${p.id}')\">삭제</button>` : \"\";\n        const comments = data.comments.map(c => `<div class=\"board-comment\"><b>${escapeHTML(c.author)}</b> <span class=\"board-muted\">${new Date(c.created_at).toLocaleString('ko-KR')}</span>${knhAuthUser && c.user_id === knhAuthUser.id ? ` <button class=\"board-btn secondary\" style=\"padding:4px 8px;font-size:12px\" onclick=\"knhDeleteComment('${c.id}','${p.id}')\">삭제</button>` : ''}<p>${escapeHTML(c.content)}</p></div>`).join(\"\") || `<div class=\"board-empty\">첫 댓글을 남겨보세요.</div>`;\n        main.innerHTML = `<div class=\"board-wrap\"><button class=\"board-btn secondary\" onclick=\"knhBoardHome()\">← 목록</button><article class=\"board-post\"><div class=\"board-post-head\"><h1>${escapeHTML(p.title)}</h1><div class=\"board-muted\">${escapeHTML(p.author)} · ${new Date(p.created_at).toLocaleString('ko-KR')} · 조회 ${p.views}</div></div><div class=\"board-post-content\">${escapeHTML(p.content)}</div><div class=\"board-top\" style=\"justify-content:flex-end\">${controls}</div></article><h2>댓글 ${data.comments.length}개</h2><section>${comments}</section><div class=\"board-comment-form\">${knhAuthUser ? `<textarea id=\"knh-comment-content\" maxlength=\"3000\" placeholder=\"댓글을 입력하세요\"></textarea><div class=\"board-top\" style=\"justify-content:flex-end\"><button class=\"board-btn\" onclick=\"knhSendComment('${p.id}')\">댓글 등록</button></div>` : `<p class=\"board-muted\">댓글을 작성하려면 로그인해 주세요.</p><button class=\"board-btn\" onclick=\"knhAuthScreen('login')\">로그인</button>`}</div></div>`;\n    } catch (e) { main.innerHTML = `<div class=\"board-empty\">${escapeHTML(e.message)}<br><br><button class=\"board-btn secondary\" onclick=\"knhBoardHome()\">목록으로</button></div>`; }\n}\n\nasync function knhSendComment(postId) {\n    const content = document.getElementById(\"knh-comment-content\").value.trim();\n    try { await knhApi(`/api/posts/${postId}/comments`, { method: \"POST\", body: JSON.stringify({ content }) }); toast(\"댓글이 등록되었습니다.\"); await knhOpenPost(postId); }\n    catch (e) { toast(e.message); }\n}\nasync function knhDeleteComment(commentId, postId) {\n    if (!confirm(\"이 댓글을 삭제할까요?\")) return;\n    try { await knhApi(`/api/comments/${commentId}`, { method: \"DELETE\" }); await knhOpenPost(postId); }\n    catch (e) { toast(e.message); }\n}\nasync function knhDeletePost(postId) {\n    if (!confirm(\"게시글을 삭제할까요? 댓글도 함께 삭제됩니다.\")) return;\n    try { await knhApi(`/api/posts/${postId}`, { method: \"DELETE\" }); toast(\"게시글이 삭제되었습니다.\"); await knhBoardHome(); }\n    catch (e) { toast(e.message); }\n}\n\n// 기존 위키 문서 이동 함수는 그대로 두고, 자유게시판만 서버 화면으로 연결한다.\nconst knhOriginalOpenPage = window.openPage;\nwindow.openPage = function(title) {\n    if (title === \"자유게시판\") {\n        currentPage = title;\n        knhBoardHome();\n        window.scrollTo({ top: 0 });\n        return;\n    }\n    return knhOriginalOpenPage(title);\n};\n\n</script>\n \n</body>\n</html>\n \r\n";

export default {
  async fetch(request) {
    if (new URL(request.url).pathname !== "/") return new Response("Not found", { status: 404 });
    return new Response(html, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
  },
};


